/*
 * Edexcel GCSE (9-1) Chemistry (1CH0) — Exam Practice Question Bank
 * 40 written exam-style questions per topic, from 1-mark to 6-mark questions.
 * Questions with diagram: true show a drawing area for students to sketch answers.
 * markScheme strings follow Edexcel mark-point style with (1) indicators;
 * 6-mark extended-response questions add Edexcel-style level descriptors.
 * [HT] marks Higher-tier-only content.
 */

const CHEMISTRY_EDEXCEL_GCSE_PRACTICE = {

  /* ─────────────────────────── Topic 1 */
  '1': {
    name: 'Key Concepts in Chemistry',
    questions: [
      { q: 'State the relative mass and the relative charge of a proton, a neutron and an electron.', marks: 3, markScheme: `• Proton: relative mass 1, relative charge +1 (1)\n• Neutron: relative mass 1, relative charge 0 (1)\n• Electron: relative mass 1/1836 (accept negligible / about 0.0005), relative charge −1 (1)` },
      { q: 'Define the term isotopes.', marks: 1, markScheme: `• Atoms of the same element with the same number of protons but different numbers of neutrons (1)` },
      { q: 'Explain why an atom has no overall charge.', marks: 2, markScheme: `• An atom contains equal numbers of protons and electrons (1)\n• The positive charge of the protons is equal and opposite to the negative charge of the electrons, so the charges cancel (1)` },
      { q: 'An atom of aluminium is represented as ²⁷₁₃Al. Determine the number of protons, neutrons and electrons in this atom.', marks: 3, markScheme: `• 13 protons (1)\n• 14 neutrons (27 − 13) (1)\n• 13 electrons (1)` },
      { q: 'Describe how the results of the alpha-particle scattering experiment led to a change in the model of the atom.', marks: 3, markScheme: `• Most alpha particles passed straight through the gold foil, so most of the atom is empty space (1)\n• A few alpha particles were deflected through large angles / bounced back, so there is a small, dense, positively charged nucleus (1)\n• This replaced the plum pudding model / Thomson model, in which positive charge was spread throughout the atom (1)` },
      { q: 'State how Bohr developed the nuclear model of the atom.', marks: 1, markScheme: `• He proposed that electrons orbit the nucleus in fixed shells / energy levels (1)` },
      { q: 'Chlorine has two isotopes: chlorine-35 (75% abundance) and chlorine-37 (25% abundance). Calculate the relative atomic mass of chlorine. [HT]', marks: 2, markScheme: `• Ar = (35 × 75 + 37 × 25) ÷ 100 (1)\n• Ar = 35.5 (1)` },
      { q: 'Bromine has two isotopes: bromine-79 (50.7% abundance) and bromine-81 (49.3% abundance). Calculate the relative atomic mass of bromine. Give your answer to one decimal place. [HT]', marks: 2, markScheme: `• Ar = (79 × 50.7 + 81 × 49.3) ÷ 100 = 7998.6 ÷ 100 (1)\n• Ar = 80.0 (1)` },
      { q: 'Explain how Mendeleev arranged the elements in his periodic table and why he left gaps.', marks: 3, markScheme: `• He arranged the elements in order of increasing relative atomic mass (1)\n• He placed elements with similar properties in the same vertical group, swapping the order where needed (1)\n• He left gaps for elements not yet discovered and predicted their properties (1)` },
      { q: 'Tellurium has a higher relative atomic mass than iodine, but Mendeleev placed tellurium before iodine. Explain why he did this and why this order is now known to be correct.', marks: 2, markScheme: `• The properties of iodine matched the other elements in its group (the halogens), so he swapped them to keep similar elements together (1)\n• Elements are now ordered by atomic number; tellurium has fewer protons than iodine but its isotopes contain more neutrons, giving a higher relative atomic mass (1)` },
      { q: 'Give the electronic configuration of (a) a magnesium atom (atomic number 12) and (b) a chlorine atom (atomic number 17).', marks: 2, markScheme: `• (a) 2.8.2 (1)\n• (b) 2.8.7 (1)` },
      { q: 'Explain how the electronic configuration of an element is related to its position in the periodic table.', marks: 2, markScheme: `• The number of occupied shells is equal to the period number (1)\n• The number of electrons in the outer shell is equal to the group number (for groups 1–7) / group 0 elements have full outer shells (1)` },
      { q: 'Describe how sodium atoms and chlorine atoms form ions when sodium reacts with chlorine.', marks: 3, markScheme: `• Each sodium atom loses one electron to form a sodium ion, Na⁺ (1)\n• Each chlorine atom gains one electron to form a chloride ion, Cl⁻ (1)\n• Both ions then have a full outer shell / the electronic configuration of a noble gas (2.8 and 2.8.8) (1)` },
      { q: 'Draw a dot-and-cross diagram for magnesium oxide. Show the outer shell electrons only and the charges on the ions.', marks: 2, diagram: true, markScheme: `Diagram should show:\n• Magnesium ion with no outer electrons shown (or a full shell of 8) and charge 2+ (1)\n• Oxide ion with 8 outer electrons, 2 of them shown as crosses (from magnesium) and charge 2− (1)` },
      { q: 'Write the formula of (a) calcium chloride, (b) aluminium oxide and (c) ammonium sulfate.', marks: 3, markScheme: `• (a) CaCl₂ (1)\n• (b) Al₂O₃ (1)\n• (c) (NH₄)₂SO₄ (1)` },
      { q: 'Describe the structure of an ionic compound such as sodium chloride.', marks: 2, markScheme: `• A giant lattice of oppositely charged ions / Na⁺ and Cl⁻ ions arranged in a regular pattern (1)\n• Held together by strong electrostatic forces of attraction acting in all directions (1)` },
      { q: 'Explain why sodium chloride has a high melting point.', marks: 2, markScheme: `• There are strong electrostatic forces of attraction between the oppositely charged ions (1)\n• A large amount of energy is needed to overcome these forces (1)` },
      { q: 'Explain why ionic compounds conduct electricity when molten or dissolved in water, but not when solid.', marks: 3, markScheme: `• In the solid the ions are held in fixed positions and cannot move (1)\n• When molten or dissolved the ions are free to move (1)\n• So the ions can carry charge through the substance (1)` },
      { q: 'State what is meant by a covalent bond.', marks: 1, markScheme: `• A bond formed when a pair of electrons is shared between two atoms (1)` },
      { q: 'Draw a dot-and-cross diagram for a molecule of ammonia, NH₃. Show the outer shell electrons only.', marks: 2, diagram: true, markScheme: `Diagram should show:\n• Three shared pairs of electrons, one between nitrogen and each hydrogen atom (1)\n• One lone pair of electrons on the nitrogen atom, giving nitrogen 8 outer electrons (1)` },
      { q: 'Explain why simple molecular substances such as methane have low boiling points.', marks: 2, markScheme: `• The intermolecular forces between the molecules are weak (1)\n• Only a small amount of energy is needed to overcome them; the covalent bonds are not broken (1)` },
      { q: 'Explain why diamond is very hard and has a very high melting point.', marks: 3, markScheme: `• Each carbon atom is covalently bonded to four other carbon atoms (1)\n• Forming a rigid giant covalent (three-dimensional) structure (1)\n• Many strong covalent bonds must be broken, which needs a large amount of energy (1)` },
      { q: 'Explain why graphite conducts electricity but diamond does not.', marks: 3, markScheme: `• In graphite each carbon atom is covalently bonded to three other carbon atoms (1)\n• So each atom has one delocalised electron that is free to move through the structure and carry charge (1)\n• In diamond all four outer electrons of each carbon are used in covalent bonds, so there are no delocalised electrons (1)` },
      { q: 'Explain why graphite is soft and can be used as a lubricant.', marks: 2, markScheme: `• Graphite is made of layers held together by weak forces between the layers (1)\n• The layers can slide over each other easily (1)` },
      { q: 'Describe the structure of graphene and give one use of graphene.', marks: 2, markScheme: `• A single layer of graphite / a sheet of carbon atoms in hexagons, one atom thick (1)\n• Use: electronics / composites / touchscreens (1)` },
      { q: 'Fullerenes such as C₆₀ are simple molecular substances. Give one use of fullerenes and explain how a property makes them suitable for that use.', marks: 2, markScheme: `• Use: lubricant / drug delivery / reinforcing materials (nanotubes) (1)\n• Linked property: spherical molecules with weak intermolecular forces roll over each other / hollow cage can carry drug molecules / nanotubes have high tensile strength (1)` },
      { q: 'Describe the bonding in a metal.', marks: 3, markScheme: `• A giant lattice of positive metal ions (1)\n• Surrounded by a sea of delocalised electrons (1)\n• Held together by strong electrostatic attraction between the positive ions and the delocalised electrons (1)` },
      { q: 'Explain why metals are malleable and are good conductors of electricity.', marks: 3, markScheme: `• The layers of positive ions can slide over each other (1)\n• Without the metallic bonding being broken, because the delocalised electrons still hold the ions together (1)\n• The delocalised electrons are free to move through the metal and carry charge (1)` },
      { q: 'Calculate the relative formula mass (Mr) of calcium carbonate, CaCO₃. (Relative atomic masses: Ca = 40, C = 12, O = 16)', marks: 2, markScheme: `• Mr = 40 + 12 + (3 × 16) (1)\n• Mr = 100 (1)` },
      { q: 'Calculate the relative formula mass (Mr) of magnesium nitrate, Mg(NO₃)₂. (Relative atomic masses: Mg = 24, N = 14, O = 16)', marks: 2, markScheme: `• Mr = 24 + 2 × (14 + 3 × 16) = 24 + 124 (1)\n• Mr = 148 (1)` },
      { q: 'A sample of an oxide of magnesium contains 2.4 g of magnesium and 1.6 g of oxygen. Determine the empirical formula of the oxide. (Mg = 24, O = 16)', marks: 3, markScheme: `• Moles: Mg = 2.4 ÷ 24 = 0.10; O = 1.6 ÷ 16 = 0.10 (1)\n• Simplest whole-number ratio Mg : O = 1 : 1 (1)\n• Empirical formula MgO (1)` },
      { q: 'A compound contains 85.7% carbon and 14.3% hydrogen by mass. Its relative formula mass is 56. Determine the empirical formula and the molecular formula of the compound. (C = 12, H = 1)', marks: 4, markScheme: `• Moles: C = 85.7 ÷ 12 = 7.14; H = 14.3 ÷ 1 = 14.3 (1)\n• Ratio C : H = 1 : 2, so empirical formula CH₂ (1)\n• Mr of CH₂ = 14; 56 ÷ 14 = 4 (1)\n• Molecular formula C₄H₈ (1)` },
      { q: '[6 marks] Describe how you would determine the empirical formula of magnesium oxide by heating magnesium ribbon in a crucible, and explain how the results would be used.', marks: 6, markScheme: `Indicative content:\n• Weigh the empty crucible and lid, then weigh again with the cleaned magnesium ribbon inside (1)\n• Heat the crucible strongly with the lid on (1)\n• Lift the lid slightly from time to time to let oxygen in while preventing magnesium oxide escaping (1)\n• Continue heating until the magnesium stops glowing, cool, reweigh and repeat heating until the mass is constant (1)\n• Mass of oxygen = mass of magnesium oxide − mass of magnesium (1)\n• Divide each mass by its relative atomic mass and find the simplest whole-number ratio of moles (1)\nLevel 3 (5–6 marks): a logically sequenced method covering measurement, heating and processing of results to find the formula\nLevel 2 (3–4 marks): a method with some detail of measurement and heating, with a partial explanation of how the formula is found\nLevel 1 (1–2 marks): isolated steps of the method or the calculation, with little linkage` },
      { q: 'Balance the equation: Na + Cl₂ → NaCl', marks: 1, markScheme: `• 2Na + Cl₂ → 2NaCl (1)` },
      { q: 'Write the balanced equation, including state symbols, for the reaction of magnesium with dilute hydrochloric acid to form magnesium chloride and hydrogen.', marks: 2, markScheme: `• Mg + 2HCl → MgCl₂ + H₂ with correct formulae and balancing (1)\n• State symbols: Mg(s), HCl(aq), MgCl₂(aq), H₂(g) (1)` },
      { q: 'Write the ionic equation, including state symbols, for the reaction between dilute hydrochloric acid and sodium hydroxide solution. [HT]', marks: 1, markScheme: `• H⁺(aq) + OH⁻(aq) → H₂O(l) (1)` },
      { q: 'Calculate the number of moles of carbon dioxide in 11 g of carbon dioxide and the number of molecules this contains. (C = 12, O = 16; Avogadro constant = 6.02 × 10²³) [HT]', marks: 3, markScheme: `• Mr CO₂ = 44 (1)\n• Moles = 11 ÷ 44 = 0.25 mol (1)\n• Molecules = 0.25 × 6.02 × 10²³ = 1.51 × 10²³ (1)` },
      { q: 'A student dissolves 5.0 g of sodium chloride in water and makes the solution up to 250 cm³. Calculate the concentration of the solution in g dm⁻³.', marks: 2, markScheme: `• Volume = 250 ÷ 1000 = 0.250 dm³ (1)\n• Concentration = 5.0 ÷ 0.250 = 20 g dm⁻³ (1)` },
      { q: 'Calculate the mass of magnesium oxide formed when 4.8 g of magnesium burns completely in oxygen. 2Mg + O₂ → 2MgO (Mg = 24, O = 16)', marks: 3, markScheme: `• Moles of Mg = 4.8 ÷ 24 = 0.20 mol (1)\n• Mole ratio Mg : MgO = 1 : 1, so 0.20 mol MgO (1)\n• Mass of MgO = 0.20 × 40 = 8.0 g (1)\n• Alternative (ratio method): 2 × 24 = 48 g Mg gives 2 × 40 = 80 g MgO, so 4.8 g Mg gives 8.0 g MgO — award all 3 marks` },
      { q: '[6 marks] 5.6 g of iron is heated with 4.0 g of sulfur. Fe + S → FeS. Determine which reactant is limiting and calculate the maximum mass of iron(II) sulfide that can form. (Fe = 56, S = 32) [HT]', marks: 6, markScheme: `• Moles of Fe = 5.6 ÷ 56 = 0.10 mol (1)\n• Moles of S = 4.0 ÷ 32 = 0.125 mol (1)\n• Ratio is 1 : 1, so iron is the limiting reactant / sulfur is in excess (1)\n• Moles of FeS formed = 0.10 mol (1)\n• Mr FeS = 56 + 32 = 88 (1)\n• Maximum mass = 0.10 × 88 = 8.8 g (1)` },
    ]
  },

  /* ─────────────────────────── Topic 2 */
  '2': {
    name: 'States of Matter and Mixtures',
    questions: [
      { q: 'Name the change of state when a gas turns into a liquid.', marks: 1, markScheme: `• Condensing / condensation (1)` },
      { q: 'Name the change of state when a solid turns directly into a gas.', marks: 1, markScheme: `• Subliming / sublimation (1)` },
      { q: 'Describe the arrangement and movement of the particles in a solid.', marks: 2, markScheme: `• Particles are close together in a regular arrangement (1)\n• Particles vibrate about fixed positions (1)` },
      { q: 'Describe the arrangement and movement of the particles in a gas.', marks: 2, markScheme: `• Particles are far apart and randomly arranged (1)\n• Particles move quickly in all directions (1)` },
      { q: 'Explain, in terms of particles, what happens when a solid melts.', marks: 3, markScheme: `• Energy is transferred to the particles so they vibrate more (1)\n• Some of the forces of attraction between the particles are overcome (1)\n• The particles can now move past each other but remain close together (1)` },
      { q: 'Explain why the temperature of a pure liquid stays the same while it is boiling.', marks: 2, markScheme: `• The energy supplied is used to overcome the forces of attraction between the particles (1)\n• Rather than to increase the kinetic energy of the particles, so the temperature does not rise (1)` },
      { q: 'Explain, using the particle model, why gases can be compressed easily but liquids cannot.', marks: 2, markScheme: `• In a gas the particles are far apart with large spaces between them, so they can be pushed closer (1)\n• In a liquid the particles are already touching / close together, so there is almost no space to compress (1)` },
      { q: 'State whether melting is a physical change or a chemical change. Justify your answer.', marks: 2, markScheme: `• Physical change (1)\n• No new substance is formed / the change is easily reversed (1)` },
      { q: 'Ethanol has a melting point of −114 °C and a boiling point of 78 °C. Predict the state of ethanol at (a) −120 °C, (b) 25 °C and (c) 100 °C.', marks: 3, markScheme: `• (a) Solid (1)\n• (b) Liquid (1)\n• (c) Gas (1)` },
      { q: 'State what is meant by a pure substance in chemistry.', marks: 1, markScheme: `• A single element or a single compound, not mixed with any other substance (1)` },
      { q: 'Explain how melting point data can be used to tell whether a substance is pure or a mixture.', marks: 2, markScheme: `• A pure substance melts at a specific / sharp temperature (1)\n• A mixture melts over a range of temperatures (usually lower than the pure substance) (1)` },
      { q: 'Pure aspirin melts at 136 °C. A student\'s sample of aspirin melts between 128 °C and 133 °C. Explain what this shows about the student\'s sample.', marks: 2, markScheme: `• The sample is impure / is a mixture (1)\n• Because it melts over a range of temperatures, below the melting point of pure aspirin (1)` },
      { q: 'Describe how sand can be separated from a mixture of sand and salt solution.', marks: 2, markScheme: `• Filter the mixture using filter paper and a funnel (1)\n• Sand is left as the residue in the filter paper; wash with distilled water and dry it (1)` },
      { q: 'Describe how to obtain pure, dry crystals of copper sulfate from copper sulfate solution.', marks: 4, markScheme: `• Heat the solution in an evaporating basin to evaporate some of the water (1)\n• Until crystals start to form on a cold glass rod dipped into the solution / until the crystallisation point is reached (1)\n• Leave the solution to cool so that crystals form (1)\n• Filter off the crystals and dry them between filter papers / in a warm oven (1)` },
      { q: 'Explain why crystallisation is used to obtain hydrated copper sulfate rather than evaporating the solution to dryness.', marks: 2, markScheme: `• Heating to dryness can remove the water of crystallisation / decompose the salt, giving a white powder (1)\n• Crystallisation gives larger, purer crystals because soluble impurities stay in the solution (1)` },
      { q: 'Describe how simple distillation is used to obtain pure water from salt solution.', marks: 4, markScheme: `• The solution is heated in a flask and the water boils (1)\n• The water vapour passes into a condenser (1)\n• The condenser is cooled by cold water, so the vapour condenses back to liquid (1)\n• Pure water is collected as the distillate; the salt remains in the flask (1)` },
      { q: 'State why anti-bumping granules are added to the flask during distillation.', marks: 1, markScheme: `• To make the liquid boil smoothly / prevent violent boiling (1)` },
      { q: 'Explain why the thermometer bulb is placed level with the side arm of the flask during distillation.', marks: 2, markScheme: `• It measures the temperature of the vapour entering the condenser (1)\n• This shows the boiling point of the substance being collected, so you know which substance is distilling (1)` },
      { q: 'Draw a labelled diagram of the apparatus used for simple distillation.', marks: 4, diagram: true, markScheme: `Diagram should show:\n• Flask containing the mixture being heated (1)\n• Thermometer with bulb at the side arm (1)\n• Condenser with cooling water entering at the bottom and leaving at the top (1)\n• Collecting vessel with distillate labelled (1)` },
      { q: 'Explain why fractional distillation, rather than simple distillation, is used to separate ethanol from water.', marks: 3, markScheme: `• Ethanol and water are both liquids with boiling points that are close together (78 °C and 100 °C) (1)\n• The fractionating column has a temperature gradient, hottest at the bottom and coolest at the top (1)\n• Ethanol, with the lower boiling point, reaches the top and condenses first, while water condenses in the column and runs back into the flask (1)` },
      { q: 'A mixture contains liquid A (boiling point 56 °C) and liquid B (boiling point 118 °C). Suggest a method to separate the liquids and state which liquid is collected first. Justify your answer.', marks: 3, markScheme: `• Fractional distillation (1)\n• Liquid A is collected first (1)\n• Because it has the lower boiling point (1)` },
      { q: 'Give one safety precaution when heating ethanol during fractional distillation, and explain why it is needed.', marks: 2, markScheme: `• Heat using an electric heater / water bath rather than a Bunsen burner (1)\n• Because ethanol is flammable (1)` },
      { q: 'Explain how paper chromatography separates the substances in a mixture.', marks: 3, markScheme: `• The paper is the stationary phase and the solvent is the mobile phase (1)\n• The substances have different solubilities in the solvent / different attractions to the paper (1)\n• More soluble substances move further up the paper, so the substances separate (1)` },
      { q: 'Describe how to set up a paper chromatography experiment to separate the dyes in an ink.', marks: 4, markScheme: `• Draw a start line (baseline) in pencil about 1–2 cm from the bottom of the paper (1)\n• Put a small spot of ink on the line (1)\n• Place the paper in a beaker of solvent with the solvent level below the baseline (1)\n• Cover with a lid and remove the paper when the solvent is near the top, then mark the solvent front (1)` },
      { q: 'Explain why the baseline on a chromatogram is drawn in pencil and not in ink.', marks: 2, markScheme: `• Pencil (graphite) is insoluble in the solvent so it does not move (1)\n• Ink would dissolve and separate, mixing with the spots and affecting the results (1)` },
      { q: 'Explain why the solvent level must be below the baseline in paper chromatography.', marks: 1, markScheme: `• Otherwise the spots would dissolve into the solvent in the beaker instead of moving up the paper (1)` },
      { q: 'On a chromatogram, a spot has moved 4.2 cm and the solvent front has moved 7.0 cm. Calculate the Rf value of the spot.', marks: 2, markScheme: `• Rf = distance moved by spot ÷ distance moved by solvent = 4.2 ÷ 7.0 (1)\n• Rf = 0.60 (1)` },
      { q: 'A dye has an Rf value of 0.45. On a chromatogram the solvent front has moved 8.0 cm. Calculate the distance moved by the dye.', marks: 2, markScheme: `• Distance = Rf × distance moved by solvent = 0.45 × 8.0 (1)\n• Distance = 3.6 cm (1)` },
      { q: 'Explain how a chromatogram shows that a food colouring is a mixture.', marks: 2, markScheme: `• The food colouring separates into more than one spot (1)\n• Each spot is a different substance (1)` },
      { q: 'Explain how paper chromatography could be used to identify the dyes in a food colouring.', marks: 3, markScheme: `• Run the food colouring alongside samples of known dyes on the same paper (1)\n• Using the same solvent and conditions (1)\n• A spot that matches a known dye in height / Rf value is likely to be that dye (1)` },
      { q: 'A spot of one substance stays on the baseline during chromatography. Explain why, and suggest what could be done to separate it.', marks: 2, markScheme: `• The substance is insoluble in the solvent used (1)\n• Repeat the chromatography using a different solvent (1)` },
      { q: 'Two inks were analysed by chromatography. Ink P gave spots with Rf values of 0.20 and 0.70. Ink Q gave spots with Rf values of 0.20, 0.50 and 0.70. Deduce whether ink P could be the same as ink Q. Justify your answer.', marks: 3, markScheme: `• Both inks contain substances with Rf values of 0.20 and 0.70, so they share two dyes (1)\n• Ink Q contains an extra substance with Rf value 0.50 (1)\n• So the inks are not the same (1)` },
      { q: 'State what is meant by potable water.', marks: 1, markScheme: `• Water that is safe to drink (1)` },
      { q: 'Describe how water from a reservoir is treated to make it potable.', marks: 3, markScheme: `• Sedimentation: large insoluble particles settle out (1)\n• Filtration through beds of sand / gravel removes smaller insoluble particles (1)\n• Chlorination kills microorganisms (1)` },
      { q: 'Explain why chlorine is added to drinking water.', marks: 2, markScheme: `• To kill bacteria / microorganisms (1)\n• Which could otherwise cause disease (1)` },
      { q: 'Explain why producing drinking water from sea water by distillation is expensive.', marks: 2, markScheme: `• Distillation needs a large amount of energy to boil the water (1)\n• This energy usually comes from fuels, which are costly (1)` },
      { q: 'Explain why deionised water, rather than tap water, is used in chemical analysis.', marks: 2, markScheme: `• Tap water contains dissolved ions (1)\n• These could react with or interfere with the substances being tested, giving false results (1)` },
      { q: 'Suggest the most suitable method to obtain: (a) salt from salt solution, (b) pure water from ink, (c) the different dyes in an ink, (d) sand from a mixture of sand and water.', marks: 4, markScheme: `• (a) Crystallisation / evaporation (1)\n• (b) Simple distillation (1)\n• (c) Paper chromatography (1)\n• (d) Filtration (1)` },
      { q: '[6 marks] Devise a method to obtain pure, dry samples of sand, salt and water from a mixture of sand and salt water.', marks: 6, markScheme: `Indicative content:\n• Filter the mixture; the sand is left in the filter paper as the residue (1)\n• Wash the sand with distilled water and dry it in a warm oven (1)\n• Heat the filtrate (salt solution) in a flask by simple distillation (1)\n• Collect the water from the condenser as the distillate (1)\n• Stop before dryness; transfer the concentrated salt solution to an evaporating basin and leave to crystallise (1)\n• Filter off and dry the salt crystals (1)\nLevel 3 (5–6 marks): a logical, complete method that obtains all three products, with correct techniques in a sensible order\nLevel 2 (3–4 marks): a method that obtains at least two products, with some correct techniques\nLevel 1 (1–2 marks): one or two appropriate techniques named, with little sequencing` },
      { q: '[6 marks] Core practical: an ink contains a mixture of water and several dyes. Describe how simple distillation and paper chromatography could be used to investigate the composition of the ink, and how the results would be analysed.', marks: 6, markScheme: `Indicative content:\n• Distil a sample of the ink: heat in a flask with a condenser attached and collect the distillate (1)\n• Record the temperature at which the distillate is collected — about 100 °C shows the solvent is water (1)\n• Draw a pencil baseline on chromatography paper and spot the ink on it, with reference dyes alongside (1)\n• Stand the paper in solvent below the baseline, cover, and remove before the solvent reaches the top; mark the solvent front (1)\n• Count the spots to find the number of dyes; compare spots with the reference dyes (1)\n• Calculate Rf = distance moved by spot ÷ distance moved by solvent and compare with known values (1)\nLevel 3 (5–6 marks): a coherent account of both techniques with clear analysis of the results\nLevel 2 (3–4 marks): a mostly correct account of one technique with some reference to the other or to analysis\nLevel 1 (1–2 marks): isolated relevant steps with little analysis` },
    ]
  },

  /* ─────────────────────────── Topic 3 */
  '3': {
    name: 'Chemical Changes',
    questions: [
      { q: 'State the name of the ion that makes a solution acidic.', marks: 1, markScheme: `• Hydrogen ion, H⁺ (1)` },
      { q: 'State the colour of methyl orange in an acidic solution and in an alkaline solution.', marks: 2, markScheme: `• Acid: red (1)\n• Alkali: yellow (1)` },
      { q: 'State the colour of phenolphthalein in an acidic solution and in an alkaline solution.', marks: 2, markScheme: `• Acid: colourless (1)\n• Alkali: pink (1)` },
      { q: 'State what is meant by (a) a base and (b) an alkali.', marks: 2, markScheme: `• (a) A substance that reacts with an acid to form a salt and water only (1)\n• (b) A base that dissolves in water, forming hydroxide ions (OH⁻) in solution (1)` },
      { q: 'Explain the difference between a strong acid and a weak acid. [HT]', marks: 2, markScheme: `• A strong acid is completely / fully dissociated (ionised) in water (1)\n• A weak acid is only partially dissociated (ionised) in water (1)` },
      { q: 'Explain the difference between a concentrated acid and a dilute acid. [HT]', marks: 2, markScheme: `• A concentrated acid has a large amount of acid (solute) dissolved per unit volume of solution (1)\n• A dilute acid has a small amount of acid dissolved per unit volume of solution (1)` },
      { q: 'The pH of an acid solution increases from 2 to 3 when it is diluted. State how the concentration of hydrogen ions has changed. [HT]', marks: 1, markScheme: `• It has decreased by a factor of 10 (1)` },
      { q: 'Hydrochloric acid and ethanoic acid solutions of the same concentration have pH values of 1 and 3. Explain this difference. [HT]', marks: 3, markScheme: `• Hydrochloric acid is a strong acid and is fully dissociated (1)\n• Ethanoic acid is a weak acid and is only partially dissociated, so it has a lower concentration of H⁺ ions (1)\n• A difference of 2 pH units means the H⁺ concentration in hydrochloric acid is 100 times greater (1)` },
      { q: 'Describe what you would observe when a piece of magnesium ribbon is added to dilute hydrochloric acid.', marks: 3, markScheme: `• Fizzing / bubbles of gas (1)\n• The magnesium gets smaller and disappears (1)\n• The solution / test tube gets warmer (1)` },
      { q: 'Write the word equation for the reaction between zinc and dilute sulfuric acid.', marks: 1, markScheme: `• Zinc + sulfuric acid → zinc sulfate + hydrogen (1)` },
      { q: 'Write the balanced equation for the reaction between calcium carbonate and dilute hydrochloric acid.', marks: 2, markScheme: `• CaCO₃ + HCl → CaCl₂ + H₂O + CO₂ with correct formulae (1)\n• Correctly balanced: CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂ (1)` },
      { q: 'Write the balanced equation, including state symbols, for the reaction between sodium hydroxide solution and dilute sulfuric acid.', marks: 2, markScheme: `• 2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O, correctly balanced (1)\n• State symbols: (aq), (aq), (aq), (l) (1)` },
      { q: 'Describe the test for hydrogen gas.', marks: 2, markScheme: `• Hold a lighted splint at the mouth of the test tube (1)\n• Hydrogen burns with a squeaky pop (1)` },
      { q: 'Describe the test for carbon dioxide gas.', marks: 2, markScheme: `• Bubble the gas through limewater (calcium hydroxide solution) (1)\n• Limewater turns milky / cloudy (1)` },
      { q: 'Name the salt produced in each reaction: (a) magnesium with hydrochloric acid, (b) copper oxide with sulfuric acid, (c) potassium hydroxide with nitric acid.', marks: 3, markScheme: `• (a) Magnesium chloride (1)\n• (b) Copper sulfate (1)\n• (c) Potassium nitrate (1)` },
      { q: 'Core practical: describe how you would investigate the change in pH when calcium hydroxide powder is added to dilute hydrochloric acid.', marks: 4, markScheme: `• Measure a fixed volume of dilute hydrochloric acid (e.g. 50 cm³) into a beaker using a measuring cylinder (1)\n• Add a small measured mass of calcium hydroxide (e.g. 0.3 g) using a balance (1)\n• Stir, then measure the pH using a pH meter / universal indicator paper and colour chart (1)\n• Repeat the additions until the calcium hydroxide is in excess and plot pH against mass added (1)` },
      { q: 'Sketch a graph to show how the pH changes as calcium hydroxide is added to dilute hydrochloric acid until it is in excess.', marks: 3, diagram: true, markScheme: `Sketch should show:\n• Starting at a low pH (about 1) (1)\n• pH rising slowly at first then sharply through pH 7 (1)\n• Levelling off at a high pH (about 12) when calcium hydroxide is in excess (1)` },
      { q: '[6 marks] Core practical: describe how to prepare a pure, dry sample of hydrated copper sulfate crystals from copper oxide and dilute sulfuric acid.', marks: 6, markScheme: `Indicative content:\n• Warm the dilute sulfuric acid gently in a beaker (1)\n• Add copper oxide powder a little at a time, stirring, until it is in excess / no more dissolves (1)\n• Filter the mixture to remove the excess copper oxide (1)\n• Heat the filtrate in an evaporating basin to evaporate some of the water until the crystallisation point (1)\n• Leave the solution to cool and crystallise (1)\n• Filter off the crystals and dry them between filter paper / in a warm place (1)\nLevel 3 (5–6 marks): a detailed, logically ordered method producing pure, dry crystals\nLevel 2 (3–4 marks): a method with most key stages, but some detail or sequencing missing\nLevel 1 (1–2 marks): some relevant steps with little logical order` },
      { q: 'Explain why excess copper oxide is added when making copper sulfate from copper oxide and sulfuric acid.', marks: 2, markScheme: `• To make sure all of the acid has reacted / is neutralised (1)\n• The excess solid can easily be removed by filtration (1)` },
      { q: 'Explain why a titration method is used to prepare sodium chloride from sodium hydroxide solution and hydrochloric acid, rather than adding an excess of one reactant.', marks: 2, markScheme: `• Both reactants are solutions / soluble (1)\n• An excess could not be removed by filtration, so the exact volumes needed for neutralisation must be found (1)` },
      { q: 'Describe how a titration can be used to prepare a pure sample of sodium chloride crystals.', marks: 4, markScheme: `• Use a pipette to add 25.0 cm³ of sodium hydroxide solution to a conical flask with a few drops of indicator (1)\n• Add hydrochloric acid from a burette until the indicator just changes colour and record the volume (1)\n• Repeat using the same volumes without the indicator (1)\n• Evaporate some of the water from the solution and leave to crystallise (1)` },
      { q: 'Use the solubility rules to state whether each substance is soluble or insoluble in water: (a) lead nitrate, (b) silver chloride, (c) barium sulfate, (d) potassium carbonate.', marks: 4, markScheme: `• (a) Soluble — all nitrates are soluble (1)\n• (b) Insoluble (1)\n• (c) Insoluble (1)\n• (d) Soluble — all potassium salts are soluble (1)` },
      { q: 'Describe how to prepare a pure, dry sample of the insoluble salt barium sulfate.', marks: 4, markScheme: `• Mix solutions of a soluble barium salt (e.g. barium chloride) and a soluble sulfate (e.g. sodium sulfate) (1)\n• Filter the mixture to collect the precipitate of barium sulfate (1)\n• Wash the precipitate with distilled water (1)\n• Dry the precipitate in a warm oven / between filter papers (1)` },
      { q: 'Write the ionic equation, including state symbols, for the formation of a silver chloride precipitate. [HT]', marks: 2, markScheme: `• Ag⁺ + Cl⁻ → AgCl (1)\n• State symbols: Ag⁺(aq) + Cl⁻(aq) → AgCl(s) (1)` },
      { q: 'State what is meant by an electrolyte.', marks: 1, markScheme: `• An ionic compound that is molten or in solution and conducts electricity / is decomposed by electricity (1)` },
      { q: 'Name the product formed at each electrode when molten lead bromide is electrolysed.', marks: 2, markScheme: `• Cathode (negative electrode): lead (1)\n• Anode (positive electrode): bromine (1)` },
      { q: 'Explain why lead ions move to the cathode during the electrolysis of molten lead bromide.', marks: 2, markScheme: `• Lead ions are positively charged (1)\n• So they are attracted to the negative electrode (cathode) (1)` },
      { q: 'Write the half equation for the reaction at the anode during the electrolysis of molten lead bromide. [HT]', marks: 2, markScheme: `• 2Br⁻ → Br₂ with correct species (1)\n• Electrons balanced: 2Br⁻ → Br₂ + 2e⁻ (1)` },
      { q: 'Predict the products at each electrode when sodium chloride solution is electrolysed using inert electrodes.', marks: 2, markScheme: `• Cathode: hydrogen (1)\n• Anode: chlorine (1)` },
      { q: 'Explain why hydrogen, not sodium, is produced at the cathode when sodium chloride solution is electrolysed.', marks: 2, markScheme: `• Sodium is more reactive than hydrogen (1)\n• So hydrogen ions (from the water) gain electrons / are discharged instead of sodium ions (1)` },
      { q: 'Predict the product at the anode when copper sulfate solution is electrolysed using inert electrodes. Explain your answer.', marks: 3, markScheme: `• Oxygen (1)\n• There are no halide ions in the solution (1)\n• So hydroxide ions (from the water) are discharged (1)` },
      { q: 'Write the half equation for the formation of oxygen from hydroxide ions at the anode. [HT]', marks: 2, markScheme: `• 4OH⁻ → O₂ + 2H₂O with correct species (1)\n• Electrons balanced: 4OH⁻ → O₂ + 2H₂O + 4e⁻ (1)` },
      { q: 'Explain, in terms of electrons, why reduction occurs at the cathode during electrolysis. [HT]', marks: 2, markScheme: `• Positive ions gain electrons at the cathode (1)\n• Gain of electrons is reduction (1)` },
      { q: 'Explain why the copper anode loses mass and the copper cathode gains mass when copper sulfate solution is electrolysed using copper electrodes.', marks: 3, markScheme: `• At the anode, copper atoms lose electrons and form Cu²⁺ ions, which go into solution (1)\n• At the cathode, Cu²⁺ ions from the solution gain electrons (1)\n• Copper atoms are deposited on the cathode (1)` },
      { q: 'Explain how electrolysis is used to purify copper.', marks: 3, markScheme: `• The impure copper is used as the anode (1)\n• A thin sheet of pure copper is used as the cathode, in copper sulfate solution (1)\n• Copper is transferred from anode to cathode; insoluble impurities fall to the bottom as a sludge (1)` },
      { q: 'During the electrolysis of copper sulfate solution with copper electrodes, the cathode gained 0.32 g but the anode lost 0.34 g. Suggest two reasons why these values are different.', marks: 2, markScheme: `• Some copper fell off the anode without being deposited on the cathode / anode contained impurities (1)\n• The cathode was not dried fully / some copper deposit flaked off the cathode when rinsed (1)` },
      { q: 'Compare the products formed at each electrode when lithium chloride is electrolysed using inert electrodes (a) when molten and (b) as an aqueous solution.', marks: 4, markScheme: `• (a) Molten: lithium at the cathode (1)\n• (a) Molten: chlorine at the anode (1)\n• (b) Aqueous: hydrogen at the cathode, because lithium is more reactive than hydrogen (1)\n• (b) Aqueous: chlorine at the anode, because chloride (halide) ions are present (1)` },
      { q: 'Sodium sulfate solution is electrolysed using inert electrodes. Name the products at each electrode, explain why they form and state the ratio of the volumes of gas produced.', marks: 5, markScheme: `• Cathode: hydrogen (1)\n• Anode: oxygen (1)\n• Hydrogen ions are discharged at the cathode because sodium is more reactive than hydrogen (1)\n• Hydroxide ions are discharged at the anode because sulfate ions are not discharged / no halide ions are present (1)\n• Volume of hydrogen : volume of oxygen = 2 : 1 (1)` },
      { q: '[6 marks] Core practical: describe how to investigate the effect of changing the current on the mass of copper deposited when copper sulfate solution is electrolysed using copper electrodes.', marks: 6, markScheme: `Indicative content:\n• Clean the copper electrodes with emery paper, rinse, dry and weigh them (1)\n• Place the electrodes in copper sulfate solution and connect them to a d.c. supply with an ammeter and variable resistor (1)\n• Keep the current constant at a chosen value for a fixed time (e.g. 20 minutes) (1)\n• Remove the electrodes, rinse with distilled water then propanone, dry and reweigh (1)\n• Repeat with fresh electrodes at different currents, keeping time and concentration the same (1)\n• Calculate the change in mass of each electrode and plot mass change against current (1)\nLevel 3 (5–6 marks): a detailed, logical method with control variables and how the results are processed\nLevel 2 (3–4 marks): a workable method with some detail, but control variables or analysis incomplete\nLevel 1 (1–2 marks): a few relevant steps with little detail or logical order` },
      { q: '[6 marks] Solutions of hydrochloric acid (a strong acid) and ethanoic acid (a weak acid) have the same concentration. Compare the pH of the two acids and how they react with magnesium ribbon, and explain the effect on pH of diluting the hydrochloric acid by a factor of 10. [HT]', marks: 6, markScheme: `Indicative content:\n• Hydrochloric acid is fully dissociated; ethanoic acid is only partially dissociated (1)\n• So hydrochloric acid has a higher concentration of H⁺ ions (1)\n• So hydrochloric acid has the lower pH (1)\n• Hydrochloric acid reacts faster with magnesium / fizzes more vigorously, as there are more frequent collisions with H⁺ ions (1)\n• With excess magnesium and equal amounts of each acid, the same total volume of hydrogen is produced (1)\n• Diluting hydrochloric acid by a factor of 10 decreases the H⁺ concentration by a factor of 10, so the pH increases by 1 (1)\nLevel 3 (5–6 marks): a detailed comparison linking dissociation, H⁺ concentration, pH and rate, with dilution correctly explained\nLevel 2 (3–4 marks): a comparison with some explanation linked to dissociation or H⁺ concentration\nLevel 1 (1–2 marks): simple statements of difference with little explanation` },
    ]
  },

  /* ─────────────────────────── Topic 4 */
  '4': {
    name: 'Extracting Metals and Equilibria',
    questions: [
      { q: 'State what is meant by an ore.', marks: 1, markScheme: `• A rock that contains enough of a metal or metal compound to make it economical to extract the metal (1)` },
      { q: 'Place these metals in order of reactivity, most reactive first: copper, potassium, iron, magnesium.', marks: 1, markScheme: `• Potassium, magnesium, iron, copper (1)` },
      { q: 'Describe what you would observe when a small piece of potassium is added to water.', marks: 3, markScheme: `• Potassium floats and moves around on the surface (1)\n• Fizzes rapidly / effervescence (1)\n• Melts into a ball and burns with a lilac flame (1)` },
      { q: 'Write the word equation for the reaction between calcium and water.', marks: 1, markScheme: `• Calcium + water → calcium hydroxide + hydrogen (1)` },
      { q: 'Explain how the reactivity of a metal is related to its tendency to form positive ions.', marks: 2, markScheme: `• The more reactive a metal, the more easily its atoms lose electrons (1)\n• So more reactive metals form positive ions (cations) more readily (1)` },
      { q: 'Predict whether a reaction will occur in each case: (a) magnesium added to copper sulfate solution, (b) copper added to magnesium sulfate solution. Explain your answers.', marks: 3, markScheme: `• (a) Reaction occurs: magnesium displaces copper (1)\n• (b) No reaction (1)\n• Because magnesium is more reactive than copper / a metal only displaces a less reactive metal from its compounds (1)` },
      { q: 'Zinc reacts with copper sulfate solution. Write the ionic equation for this reaction and identify which species is oxidised and which is reduced. [HT]', marks: 3, markScheme: `• Zn + Cu²⁺ → Zn²⁺ + Cu (1)\n• Zinc is oxidised because it loses electrons (1)\n• Cu²⁺ ions are reduced because they gain electrons (1)` },
      { q: 'Define oxidation and reduction in terms of oxygen.', marks: 2, markScheme: `• Oxidation is the gain of oxygen (1)\n• Reduction is the loss of oxygen (1)` },
      { q: 'Define oxidation and reduction in terms of electrons. [HT]', marks: 2, markScheme: `• Oxidation is the loss of electrons (1)\n• Reduction is the gain of electrons (1)` },
      { q: 'Describe a method, using metal salt solutions, to place iron, zinc, copper and an unknown metal X in order of reactivity.', marks: 4, markScheme: `• Add a small piece of each metal to solutions of the salts of each of the other metals (e.g. in a spotting tile) (1)\n• Keep the concentration and volume of the solutions and the size of the metal pieces the same (1)\n• Look for signs of a displacement reaction, such as a coating forming on the metal / colour change / temperature rise (1)\n• The metal that displaces the most other metals is the most reactive (1)` },
      { q: 'Describe how the reactions of metals with dilute hydrochloric acid could be used to place magnesium, zinc, iron and copper in order of reactivity.', marks: 5, markScheme: `• Use the same volume and concentration of dilute hydrochloric acid for each metal (1)\n• Use pieces of metal of the same mass and surface area (1)\n• Observe the rate of bubbling / measure the temperature rise for each metal (1)\n• The more vigorous the reaction, the more reactive the metal: magnesium, then zinc, then iron (1)\n• Copper does not react with dilute hydrochloric acid, so it is the least reactive (1)` },
      { q: 'Explain why iron can be extracted from iron oxide by heating with carbon, but aluminium must be extracted by electrolysis.', marks: 3, markScheme: `• Iron is less reactive than carbon (1)\n• So carbon can reduce iron oxide / remove the oxygen from it (1)\n• Aluminium is more reactive than carbon, so carbon cannot reduce aluminium oxide (1)` },
      { q: 'Balance the equation for the reduction of iron(III) oxide by carbon monoxide: Fe₂O₃ + CO → Fe + CO₂', marks: 1, markScheme: `• Fe₂O₃ + 3CO → 2Fe + 3CO₂ (1)` },
      { q: 'In the reaction Fe₂O₃ + 3CO → 2Fe + 3CO₂, identify the substance that is reduced. Justify your answer.', marks: 2, markScheme: `• Iron(III) oxide (1)\n• Because it loses oxygen (1)` },
      { q: 'Calculate the percentage by mass of iron in iron(III) oxide, Fe₂O₃. (Fe = 56, O = 16)', marks: 2, markScheme: `• Mr Fe₂O₃ = 160 and mass of iron = 112 (1)\n• % iron = 112 ÷ 160 × 100 = 70% (1)` },
      { q: 'Explain why gold is found as the uncombined element in the Earth\'s crust.', marks: 2, markScheme: `• Gold is very unreactive (1)\n• So it does not react with oxygen, water or other substances to form compounds (1)` },
      { q: 'Explain why aluminium oxide is dissolved in molten cryolite during the extraction of aluminium.', marks: 2, markScheme: `• It lowers the melting point of the electrolyte (1)\n• So less energy is needed, reducing costs (1)` },
      { q: 'Explain why the carbon anodes must be replaced regularly during the extraction of aluminium.', marks: 3, markScheme: `• Oxygen is produced at the anodes (1)\n• At the high temperature the oxygen reacts with the carbon (1)\n• Forming carbon dioxide, so the anodes burn away (1)` },
      { q: 'Write the half equation for the reaction at the cathode during the extraction of aluminium. [HT]', marks: 2, markScheme: `• Al³⁺ → Al with electrons on the left (1)\n• Balanced: Al³⁺ + 3e⁻ → Al (1)` },
      { q: 'Explain why extracting aluminium by electrolysis is expensive.', marks: 2, markScheme: `• Large amounts of electricity are needed (1)\n• A high temperature must be maintained to keep the electrolyte molten (1)` },
      { q: 'Describe how phytoextraction is used to extract copper from low-grade ores. [HT]', marks: 4, markScheme: `• Plants are grown on soil containing low-grade copper ore (1)\n• The plants absorb copper compounds through their roots (1)\n• The plants are harvested and burned (1)\n• Copper compounds are extracted from the ash and copper is obtained by electrolysis / displacement with scrap iron (1)` },
      { q: 'Describe how bacteria are used to extract metals in bioleaching. [HT]', marks: 2, markScheme: `• Bacteria feed on / break down low-grade ores (1)\n• Producing a solution (leachate) containing metal compounds, from which the metal is extracted (1)` },
      { q: 'Give two advantages and one disadvantage of biological methods of metal extraction. [HT]', marks: 3, markScheme: `• Advantage: can extract metal economically from low-grade ores (1)\n• Advantage: less energy used / less damage to the environment than mining and smelting (1)\n• Disadvantage: the process is very slow (1)` },
      { q: 'Explain the advantages of recycling metals.', marks: 3, markScheme: `• Conserves limited / finite supplies of metal ores (1)\n• Uses less energy than extracting the metal from its ore (1)\n• Reduces waste going to landfill and the environmental damage caused by mining (1)` },
      { q: 'State the four stages considered in a life cycle assessment of a product.', marks: 4, markScheme: `• Obtaining the raw materials (1)\n• Manufacturing the product (1)\n• Using the product (1)\n• Disposal at the end of its life (1)` },
      { q: 'Give two reasons why life cycle assessments may not be completely objective.', marks: 2, markScheme: `• Some effects, such as pollution, are hard to give numerical values to, so value judgements are made (1)\n• They can be shortened or used selectively, e.g. by companies to support advertising claims (1)` },
      { q: '[6 marks] A company compares a glass bottle and a plastic bottle. Glass bottle: 4.5 MJ of energy to manufacture, 300 g of CO₂ released, can be reused about 20 times and is widely recycled. Plastic bottle: 2.0 MJ of energy to manufacture, 120 g of CO₂ released, made from crude oil, used once and less often recycled. Evaluate which bottle has the lower environmental impact.', marks: 6, markScheme: `Indicative content:\n• The plastic bottle needs less than half the energy to manufacture (2.0 MJ vs 4.5 MJ) (1)\n• The plastic bottle releases less CO₂ per bottle made (120 g vs 300 g) (1)\n• Plastic is made from crude oil, a finite resource, and is not biodegradable if sent to landfill (1)\n• The glass bottle can be reused about 20 times, so its impact per use is much smaller (e.g. 300 ÷ 20 = 15 g CO₂ per use) (1)\n• Glass is widely recycled; glass is heavier so transport uses more fuel (1)\n• Conclusion: if reused, the glass bottle has the lower overall impact; if used once, the plastic bottle does (1)\nLevel 3 (5–6 marks): uses the data for both bottles across several stages of the life cycle, reaching a supported conclusion\nLevel 2 (3–4 marks): uses some data to compare the bottles, with a simple conclusion\nLevel 1 (1–2 marks): simple statements about one or both bottles with little use of the data` },
      { q: 'State what is meant by a reversible reaction.', marks: 1, markScheme: `• A reaction in which the products can react to form the original reactants (1)` },
      { q: 'Describe what happens when blue hydrated copper sulfate is heated, and then water is added to the product.', marks: 3, markScheme: `• On heating, the blue crystals turn white / anhydrous copper sulfate forms (1)\n• Water (steam) is given off (1)\n• When water is added, the white solid turns blue again and heat is released (1)` },
      { q: 'Ammonium chloride is heated at the bottom of a test tube. Write the equation for the reaction and describe what is seen near the cool top of the tube.', marks: 2, markScheme: `• NH₄Cl ⇌ NH₃ + HCl (1)\n• A white solid reforms near the cool top of the tube as ammonia and hydrogen chloride recombine (1)` },
      { q: 'Explain what is meant by a dynamic equilibrium.', marks: 3, markScheme: `• The forward and backward reactions are both still happening (1)\n• At the same rate (1)\n• So the concentrations of reactants and products stay constant (in a closed system) (1)` },
      { q: 'State the conditions used in the Haber process.', marks: 3, markScheme: `• Temperature of about 450 °C (1)\n• Pressure of about 200 atmospheres (1)\n• Iron catalyst (1)` },
      { q: 'Write the balanced equation for the Haber process and give the sources of the raw materials.', marks: 3, markScheme: `• N₂ + 3H₂ ⇌ 2NH₃ (1)\n• Nitrogen from the air (1)\n• Hydrogen from natural gas (methane) (1)` },
      { q: 'Explain the effect of increasing the pressure on the equilibrium yield of ammonia in the Haber process. [HT]', marks: 3, markScheme: `• Increasing pressure shifts the position of equilibrium towards the side with fewer molecules of gas (1)\n• There are 4 molecules of gas on the left and 2 on the right (1)\n• So the equilibrium shifts to the right and the yield of ammonia increases (1)` },
      { q: 'The forward reaction in the Haber process is exothermic. Explain the effect of increasing the temperature on the equilibrium yield of ammonia. [HT]', marks: 3, markScheme: `• Increasing temperature shifts the equilibrium in the direction of the endothermic reaction (1)\n• This is the backward reaction (1)\n• So the yield of ammonia decreases (1)` },
      { q: 'Explain the effect of the iron catalyst on the rate of the Haber process and on the yield of ammonia.', marks: 2, markScheme: `• The catalyst increases the rate, so equilibrium is reached more quickly (1)\n• It does not change the position of equilibrium / the yield (1)` },
      { q: 'Explain why the unreacted nitrogen and hydrogen are recycled in the Haber process.', marks: 2, markScheme: `• Only a fraction of the gases react on each pass through the reactor (1)\n• Recycling them means the raw materials are not wasted and the overall conversion is high (1)` },
      { q: 'Predict and explain the effect of adding more nitrogen on the position of equilibrium in the Haber process. [HT]', marks: 2, markScheme: `• The position of equilibrium shifts to the right (1)\n• To remove / use up the added nitrogen, so more ammonia forms (1)` },
      { q: 'For the reaction 2SO₂(g) + O₂(g) ⇌ 2SO₃(g), the forward reaction is exothermic. Predict and explain the effect on the equilibrium yield of SO₃ of (a) decreasing the temperature and (b) decreasing the pressure. [HT]', marks: 4, markScheme: `• (a) Yield of SO₃ increases (1)\n• Because equilibrium shifts in the exothermic direction / to the right (1)\n• (b) Yield of SO₃ decreases (1)\n• Because equilibrium shifts to the side with more gas molecules / 3 on the left, 2 on the right (1)` },
      { q: '[6 marks] Explain why a temperature of 450 °C and a pressure of 200 atmospheres are chosen for the Haber process. [HT]', marks: 6, markScheme: `Indicative content:\n• The forward reaction is exothermic, so a lower temperature would give a higher equilibrium yield (1)\n• But a lower temperature gives a very slow rate of reaction (1)\n• 450 °C is a compromise between a reasonable yield and a fast enough rate (1)\n• A higher pressure shifts equilibrium to the right (fewer gas molecules), increasing yield and also increasing rate (1)\n• But very high pressures are expensive to generate and need costly, strong equipment, and are a safety risk (1)\n• 200 atm is a compromise between yield, rate and cost; the iron catalyst also increases the rate (1)\nLevel 3 (5–6 marks): a full explanation of both conditions, linking yield, rate, cost and safety as a compromise\nLevel 2 (3–4 marks): explains the effect of at least one condition on yield or rate with some reference to compromise\nLevel 1 (1–2 marks): simple statements about the conditions with little explanation` },
    ]
  },

  /* ─────────────────────────── Topic 5 */
  '5': {
    name: 'Separate Chemistry 1',
    questions: [
      { q: 'Give three typical properties of transition metals that are not shown by Group 1 metals.', marks: 3, markScheme: `Any three from:\n• High melting point (1)\n• High density (1)\n• Form coloured compounds / act as catalysts (1)` },
      { q: 'State the conditions needed for iron to rust.', marks: 2, markScheme: `• Water (1)\n• Oxygen / air (1)` },
      { q: 'Name the substance formed when iron rusts and explain why rusting is an example of oxidation.', marks: 2, markScheme: `• Hydrated iron(III) oxide (1)\n• Iron gains oxygen / iron atoms lose electrons (1)` },
      { q: 'Describe an experiment to show that both air and water are needed for iron to rust.', marks: 4, markScheme: `• Set up three test tubes, each containing an iron nail (1)\n• Tube 1: nail in tap water open to the air (control) (1)\n• Tube 2: nail in boiled water with a layer of oil on top, so there is no air (1)\n• Tube 3: nail with anhydrous calcium chloride (drying agent) in a stoppered tube, so there is no water; only the nail in tube 1 rusts (1)` },
      { q: 'Explain how painting a steel bridge prevents rusting.', marks: 2, markScheme: `• The paint acts as a barrier (1)\n• Which keeps out oxygen and water (1)` },
      { q: 'Explain how galvanising protects iron from rusting even when the coating is scratched.', marks: 3, markScheme: `• Galvanised iron is coated with zinc (1)\n• Zinc is more reactive than iron (1)\n• So zinc is oxidised / loses electrons in preference to iron (sacrificial protection) (1)` },
      { q: 'Explain why blocks of magnesium are attached to the steel hulls of ships.', marks: 2, markScheme: `• Magnesium is more reactive than iron (1)\n• So it corrodes instead of the steel / provides sacrificial protection (1)` },
      { q: 'Explain why aluminium objects do not corrode easily, even though aluminium is a reactive metal.', marks: 2, markScheme: `• A thin layer of aluminium oxide forms on the surface (1)\n• This layer protects the metal underneath from further reaction (1)` },
      { q: 'Describe how a steel spoon can be electroplated with silver.', marks: 4, markScheme: `• The spoon is used as the cathode (negative electrode) (1)\n• A piece of silver is used as the anode (positive electrode) (1)\n• The electrolyte is a solution containing silver ions, e.g. silver nitrate solution (1)\n• When a current flows, silver ions gain electrons and silver is deposited on the spoon (1)` },
      { q: 'Give two reasons why metal objects are electroplated.', marks: 2, markScheme: `• To improve resistance to corrosion (1)\n• To improve appearance / make it look more attractive (1)` },
      { q: 'Explain why alloys are harder than pure metals.', marks: 3, markScheme: `• Alloys contain atoms of different sizes (1)\n• These distort the regular layers of atoms (1)\n• So it is more difficult for the layers to slide over each other (1)` },
      { q: 'Draw diagrams to show the arrangement of atoms in a pure metal and in an alloy.', marks: 2, diagram: true, markScheme: `Diagrams should show:\n• Pure metal: regular layers of identical atoms (1)\n• Alloy: atoms of a different size distorting the layers (1)` },
      { q: 'Calculate the percentage of gold in 18-carat gold.', marks: 2, markScheme: `• 18 ÷ 24 × 100 (1)\n• = 75% (1)` },
      { q: 'Explain why gold used for jewellery is usually alloyed with copper or silver.', marks: 2, markScheme: `• Pure gold is too soft (1)\n• The alloy is harder / more resistant to wear and bending (1)` },
      { q: 'Aluminium alloys are used to make aircraft. Explain why.', marks: 2, markScheme: `• They have a low density (1)\n• And are stronger than pure aluminium (1)` },
      { q: 'A student calculated that a reaction should produce 12.0 g of product, but only obtained 9.0 g. Calculate the percentage yield.', marks: 2, markScheme: `• % yield = (actual ÷ theoretical) × 100 = (9.0 ÷ 12.0) × 100 (1)\n• = 75% (1)` },
      { q: 'Give three reasons why the actual yield of a reaction is often less than the theoretical yield.', marks: 3, markScheme: `• The reaction may be incomplete / reversible (1)\n• Some product is lost when it is separated from the reaction mixture / transferred (1)\n• Some reactants may take part in unexpected side reactions (1)` },
      { q: 'Calculate the maximum mass of calcium oxide that could be made by heating 25 g of calcium carbonate. A student obtained 11.2 g. Calculate the percentage yield. CaCO₃ → CaO + CO₂ (Ca = 40, C = 12, O = 16)', marks: 4, markScheme: `• Moles CaCO₃ = 25 ÷ 100 = 0.25 mol (1)\n• Theoretical mass CaO = 0.25 × 56 = 14 g (1)\n• % yield = 11.2 ÷ 14 × 100 (1)\n• = 80% (1)` },
      { q: 'Hydrogen is made by the reaction CH₄ + H₂O → CO + 3H₂. Calculate the atom economy for making hydrogen. (C = 12, H = 1, O = 16)', marks: 3, markScheme: `• Total Mr of reactants = 16 + 18 = 34 (1)\n• Mr of desired product = 3 × 2 = 6 (1)\n• Atom economy = 6 ÷ 34 × 100 = 17.6% (1)` },
      { q: 'Iron is made by the reaction Fe₂O₃ + 3CO → 2Fe + 3CO₂. Calculate the atom economy for making iron. (Fe = 56, C = 12, O = 16)', marks: 3, markScheme: `• Total Mr of reactants = 160 + (3 × 28) = 244 (1)\n• Mass of desired product = 2 × 56 = 112 (1)\n• Atom economy = 112 ÷ 244 × 100 = 45.9% (1)` },
      { q: 'Explain why chemical companies prefer reactions with a high atom economy.', marks: 2, markScheme: `• Less of the reactants is turned into waste products (1)\n• So the process is more sustainable / uses fewer resources and is cheaper (1)` },
      { q: '[6 marks] A chemical can be made by two routes. Route A: atom economy 100%, percentage yield 60%, temperature 450 °C, uses a reversible reaction. Route B: atom economy 45%, percentage yield 95%, temperature 30 °C, the by-product can be sold. Evaluate which route a company should choose. [HT]', marks: 6, markScheme: `Indicative content:\n• Route A has the higher atom economy, so no atoms are wasted as by-products (1)\n• Route A has a low yield, but as it is reversible, unreacted materials could be recycled (1)\n• Route A needs a high temperature, so energy costs are high and more fuel is burned (1)\n• Route B has a high yield, so more of the reactants is converted to product (1)\n• Route B has a low atom economy, but the by-product can be sold, reducing the effective waste and cost (1)\n• Route B operates at a low temperature, so energy costs are lower; a justified conclusion based on these factors (1)\nLevel 3 (5–6 marks): weighs atom economy, yield, energy and by-products for both routes, reaching a justified conclusion\nLevel 2 (3–4 marks): compares at least two factors for both routes, with a simple conclusion\nLevel 1 (1–2 marks): simple statements about one or two factors with no clear conclusion` },
      { q: 'Calculate the concentration, in mol dm⁻³, of a solution containing 0.40 mol of solute in 250 cm³ of solution. [HT]', marks: 2, markScheme: `• Volume = 0.250 dm³ (1)\n• Concentration = 0.40 ÷ 0.250 = 1.6 mol dm⁻³ (1)` },
      { q: 'Convert a concentration of 0.20 mol dm⁻³ of sodium hydroxide, NaOH, into g dm⁻³. (Na = 23, O = 16, H = 1) [HT]', marks: 2, markScheme: `• Mr NaOH = 40 (1)\n• Concentration = 0.20 × 40 = 8.0 g dm⁻³ (1)` },
      { q: '[6 marks] Core practical: describe how to carry out an acid–alkali titration to find the exact volume of dilute hydrochloric acid needed to neutralise 25.0 cm³ of sodium hydroxide solution.', marks: 6, markScheme: `Indicative content:\n• Use a pipette (with filler) to transfer 25.0 cm³ of sodium hydroxide solution into a conical flask (1)\n• Add a few drops of a suitable indicator, e.g. phenolphthalein or methyl orange (1)\n• Fill a burette with hydrochloric acid and record the initial reading at eye level, reading the bottom of the meniscus (1)\n• Add the acid while swirling the flask, adding drop by drop near the end point (1)\n• Stop when the indicator just changes colour permanently; record the final reading and calculate the titre (1)\n• Repeat until concordant results (within 0.10 cm³) are obtained and calculate the mean titre (1)\nLevel 3 (5–6 marks): a detailed, logically sequenced method with correct apparatus, end-point detection and repeats\nLevel 2 (3–4 marks): a workable method with correct apparatus but some detail missing\nLevel 1 (1–2 marks): some correct apparatus or steps with little sequencing` },
      { q: 'A student\'s titres were 22.50 cm³ (rough), 22.10 cm³, 22.15 cm³ and 22.20 cm³. Calculate the mean titre using concordant results.', marks: 2, markScheme: `• Use the concordant titres 22.10, 22.15 and 22.20 cm³ (ignore the rough) (1)\n• Mean = 22.15 cm³ (1)` },
      { q: '25.0 cm³ of 0.100 mol dm⁻³ sodium hydroxide solution is neutralised by 20.0 cm³ of hydrochloric acid. Calculate the concentration of the hydrochloric acid in mol dm⁻³. NaOH + HCl → NaCl + H₂O [HT]', marks: 3, markScheme: `• Moles NaOH = 0.100 × 25.0 ÷ 1000 = 0.00250 mol (1)\n• Moles HCl = 0.00250 mol (1 : 1 ratio) (1)\n• Concentration HCl = 0.00250 ÷ 0.0200 = 0.125 mol dm⁻³ (1)` },
      { q: '25.0 cm³ of 0.200 mol dm⁻³ sodium hydroxide solution is neutralised by 20.0 cm³ of sulfuric acid. Calculate the concentration of the sulfuric acid in mol dm⁻³. 2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O [HT]', marks: 4, markScheme: `• Moles NaOH = 0.200 × 0.0250 = 0.00500 mol (1)\n• Moles H₂SO₄ = 0.00500 ÷ 2 = 0.00250 mol (1)\n• Concentration = 0.00250 ÷ 0.0200 (1)\n• = 0.125 mol dm⁻³ (1)` },
      { q: 'Calculate the volume, in dm³, of 0.25 mol of carbon dioxide at room temperature and pressure. (Molar volume = 24 dm³ at RTP) [HT]', marks: 2, markScheme: `• Volume = 0.25 × 24 (1)\n• = 6.0 dm³ (1)` },
      { q: 'Calculate the volume of hydrogen, at RTP, produced when 2.4 g of magnesium reacts with excess hydrochloric acid. Mg + 2HCl → MgCl₂ + H₂ (Mg = 24; molar volume = 24 dm³ at RTP) [HT]', marks: 3, markScheme: `• Moles Mg = 2.4 ÷ 24 = 0.10 mol (1)\n• Moles H₂ = 0.10 mol (1 : 1 ratio) (1)\n• Volume = 0.10 × 24 = 2.4 dm³ (1)` },
      { q: 'Calculate the volume of oxygen needed to burn 50 cm³ of methane completely. All volumes are measured at the same temperature and pressure. CH₄ + 2O₂ → CO₂ + 2H₂O [HT]', marks: 2, markScheme: `• Mole ratio CH₄ : O₂ = 1 : 2, so volume ratio is 1 : 2 (Avogadro’s law) (1)\n• Volume of oxygen = 100 cm³ (1)` },
      { q: 'Name the three elements provided by NPK fertilisers and explain why farmers use fertilisers.', marks: 2, markScheme: `• Nitrogen, phosphorus and potassium (1)\n• To replace the elements used by crops / to increase plant growth and crop yield (1)` },
      { q: 'Ammonium sulfate is a fertiliser. Name the two reactants used to make it and write a balanced equation for the reaction.', marks: 3, markScheme: `• Ammonia and sulfuric acid (1)\n• NH₃ + H₂SO₄ → (NH₄)₂SO₄ with correct formulae (1)\n• Balanced: 2NH₃ + H₂SO₄ → (NH₄)₂SO₄ (1)` },
      { q: 'Compare the production of ammonium sulfate in the laboratory with its production in industry.', marks: 4, markScheme: `• Laboratory: small-scale batch process using titration and crystallisation (1)\n• Laboratory: starts from dilute solutions of ammonia and sulfuric acid bought from suppliers (1)\n• Industry: large-scale continuous process with several stages (1)\n• Industry: raw materials made on site from air, natural gas, sulfur and water (Haber process and Contact process) (1)` },
      { q: 'Explain why a catalyst is used in industrial processes that involve a dynamic equilibrium, such as the Haber process, even though it does not change the equilibrium yield. [HT]', marks: 3, markScheme: `• The catalyst increases the rate of both the forward and backward reactions, so equilibrium is reached more quickly (1)\n• So more product is made per hour / in a given time (1)\n• It allows an acceptable rate at a lower temperature, saving energy and cost (1)` },
      { q: 'Describe how a simple chemical cell produces a voltage.', marks: 2, markScheme: `• Two different metals are placed in an electrolyte (1)\n• A chemical reaction produces a voltage until one of the reactants is used up (1)` },
      { q: 'Explain why non-rechargeable alkaline batteries eventually stop working.', marks: 2, markScheme: `• The chemical reactions stop when one of the reactants has been used up (1)\n• The reactions cannot be reversed, so the battery cannot be recharged (1)` },
      { q: 'Write the overall equation for the reaction in a hydrogen–oxygen fuel cell and give two advantages of fuel cells over petrol engines.', marks: 3, markScheme: `• 2H₂ + O₂ → 2H₂O (1)\n• The only product is water / no carbon dioxide or pollutants at the point of use (1)\n• More efficient / quieter / no moving parts / produce electricity continuously while fuel is supplied (1)` },
      { q: 'Draw a labelled diagram of a hydrogen–oxygen fuel cell.', marks: 3, diagram: true, markScheme: `Diagram should show:\n• Hydrogen entering at one electrode and oxygen (air) at the other (1)\n• Electrolyte between the two electrodes (1)\n• Water leaving the cell and an external circuit connecting the electrodes (1)` },
      { q: '[6 marks] Evaluate the use of hydrogen fuel cells, compared with rechargeable batteries, to power cars.', marks: 6, markScheme: `Indicative content:\n• Fuel cells produce only water at the point of use; batteries also produce no emissions while driving (1)\n• Fuel cell cars can be refuelled quickly; batteries take a long time to recharge (1)\n• Fuel cells give a longer range than many batteries (1)\n• Hydrogen is a flammable gas that is difficult and expensive to store and transport, and there are few filling stations (1)\n• Hydrogen is often made from natural gas or by electrolysis using fossil-fuel electricity, releasing CO₂ (1)\n• Batteries contain toxic / scarce metals and have a limited number of charge cycles; justified conclusion (1)\nLevel 3 (5–6 marks): a balanced evaluation of both technologies with a justified conclusion\nLevel 2 (3–4 marks): advantages and disadvantages of at least one technology, with some comparison\nLevel 1 (1–2 marks): isolated statements about fuel cells or batteries` },
    ]
  },

  /* ─────────────────────────── Topic 6 */
  '6': {
    name: 'Groups in the Periodic Table',
    questions: [
      { q: 'State why lithium, sodium and potassium are placed in Group 1 of the periodic table.', marks: 1, markScheme: `• They each have one electron in their outer shell (1)` },
      { q: 'Give two physical properties of the alkali metals that are different from most other metals.', marks: 2, markScheme: `• They are soft / can be cut with a knife (1)\n• They have low densities / low melting points (1)` },
      { q: 'Explain why the alkali metals are stored under oil.', marks: 2, markScheme: `• They react quickly with oxygen and with water (vapour) in the air (1)\n• The oil keeps out air and water (1)` },
      { q: 'Describe what you would observe when a small piece of sodium is added to a trough of water.', marks: 3, markScheme: `• Sodium floats on the water (1)\n• Fizzes / effervescence and moves around on the surface (1)\n• Melts into a silvery ball and gets smaller until it disappears (1)` },
      { q: 'Write the balanced equation, including state symbols, for the reaction of lithium with water.', marks: 3, markScheme: `• 2Li + 2H₂O → 2LiOH + H₂ with correct formulae (1)\n• Correctly balanced (1)\n• State symbols: Li(s), H₂O(l), LiOH(aq), H₂(g) (1)` },
      { q: 'Universal indicator is added to the water after potassium has reacted with it. State the colour seen and explain why.', marks: 2, markScheme: `• Purple / blue (1)\n• An alkaline solution of potassium hydroxide is formed (1)` },
      { q: 'Compare the reactions of lithium, sodium and potassium with water.', marks: 3, markScheme: `• All three fizz and produce hydrogen and a metal hydroxide (1)\n• Reactivity increases down the group: lithium reacts steadily, sodium more vigorously and melts (1)\n• Potassium reacts most violently, melting and burning with a lilac flame (1)` },
      { q: 'Explain why potassium is more reactive than sodium.', marks: 4, markScheme: `• A potassium atom has more occupied shells / its outer electron is further from the nucleus (1)\n• There is more shielding by inner electrons (1)\n• So there is weaker attraction between the nucleus and the outer electron (1)\n• So the outer electron is lost more easily (1)` },
      { q: 'Rubidium is below potassium in Group 1. Predict how rubidium reacts with water and give one product of the reaction.', marks: 2, markScheme: `• Reacts more violently than potassium / explosively (1)\n• Hydrogen / rubidium hydroxide (1)` },
      { q: 'State why the elements in Group 7 have similar chemical properties.', marks: 1, markScheme: `• They all have seven electrons in their outer shell (1)` },
      { q: 'Give the colour and physical state at room temperature of (a) chlorine, (b) bromine and (c) iodine.', marks: 3, markScheme: `• (a) Chlorine: yellow-green / pale green gas (1)\n• (b) Bromine: red-brown liquid (1)\n• (c) Iodine: dark grey / black solid (1)` },
      { q: 'Describe the trend in melting point and boiling point down Group 7.', marks: 1, markScheme: `• Melting and boiling points increase down the group (1)` },
      { q: 'Astatine is below iodine in Group 7. Predict the physical state of astatine at room temperature and its reactivity compared with iodine.', marks: 2, markScheme: `• Solid (1)\n• Less reactive than iodine (1)` },
      { q: 'Describe the test for chlorine gas.', marks: 2, markScheme: `• Hold damp blue litmus paper in the gas (1)\n• The litmus paper is bleached / turns white (it may turn red first) (1)` },
      { q: 'Write the balanced equation for the reaction between sodium and chlorine.', marks: 2, markScheme: `• Na + Cl₂ → NaCl with correct formulae (1)\n• Balanced: 2Na + Cl₂ → 2NaCl (1)` },
      { q: 'Describe what you would observe when iron wool is heated and placed in a gas jar of chlorine, and name the product.', marks: 2, markScheme: `• Iron glows / burns brightly and brown smoke / solid forms (1)\n• Iron(III) chloride (1)` },
      { q: 'Hydrogen reacts with chlorine to form hydrogen chloride. Write the balanced equation and explain what happens when hydrogen chloride dissolves in water.', marks: 3, markScheme: `• H₂ + Cl₂ → 2HCl (1)\n• Hydrogen chloride dissolves to form hydrochloric acid (1)\n• Because it forms H⁺ ions in solution, so the solution is acidic (1)` },
      { q: 'Explain why hydrogen chloride gas dissolved in methylbenzene does not turn blue litmus red, but hydrogen chloride dissolved in water does.', marks: 2, markScheme: `• In water, hydrogen chloride ionises / dissociates to form H⁺ ions (1)\n• In methylbenzene it stays as molecules, so no H⁺ ions are formed (1)` },
      { q: 'Explain the trend in reactivity down Group 7.', marks: 4, markScheme: `• Reactivity decreases down the group (1)\n• The outer shell is further from the nucleus / there is more shielding (1)\n• So there is weaker attraction between the nucleus and an incoming electron (1)\n• So it is harder for the atom to gain an electron (1)` },
      { q: 'Chlorine water is added to potassium bromide solution. Describe what you would see and write a balanced equation for the reaction.', marks: 3, markScheme: `• The colourless solution turns orange / yellow-orange (1)\n• Cl₂ + KBr → KCl + Br₂ with correct formulae (1)\n• Balanced: Cl₂ + 2KBr → 2KCl + Br₂ (1)` },
      { q: 'Explain why there is no reaction when iodine solution is added to potassium chloride solution.', marks: 2, markScheme: `• Iodine is less reactive than chlorine (1)\n• So iodine cannot displace chlorine from its compound (1)` },
      { q: 'Write the ionic equation for the reaction between chlorine and bromide ions. [HT]', marks: 2, markScheme: `• Cl₂ + Br⁻ → Cl⁻ + Br₂ with correct species (1)\n• Balanced: Cl₂ + 2Br⁻ → 2Cl⁻ + Br₂ (1)` },
      { q: 'Explain, in terms of electrons, why the reaction between chlorine and potassium bromide is a redox reaction. [HT]', marks: 3, markScheme: `• Chlorine gains electrons to form chloride ions, so it is reduced (1)\n• Bromide ions lose electrons to form bromine, so they are oxidised (1)\n• Reduction and oxidation happen at the same time, so it is a redox reaction (1)` },
      { q: 'Write half equations for the oxidation and reduction in the reaction between chlorine and iodide ions. [HT]', marks: 2, markScheme: `• Reduction: Cl₂ + 2e⁻ → 2Cl⁻ (1)\n• Oxidation: 2I⁻ → I₂ + 2e⁻ (1)` },
      { q: 'Predict whether a reaction occurs in each of the following mixtures: chlorine with potassium iodide, bromine with potassium chloride, bromine with potassium iodide, iodine with potassium bromide.', marks: 4, markScheme: `• Chlorine + potassium iodide: reaction (iodine formed) (1)\n• Bromine + potassium chloride: no reaction (1)\n• Bromine + potassium iodide: reaction (iodine formed) (1)\n• Iodine + potassium bromide: no reaction (1)` },
      { q: 'Describe a method to show the order of reactivity of chlorine, bromine and iodine using displacement reactions.', marks: 4, markScheme: `• Add a few drops of each halogen solution to solutions of the other halide ions (e.g. potassium chloride, bromide and iodide) in test tubes or a spotting tile (1)\n• Use the same volumes and concentrations each time (1)\n• Look for a colour change showing that a displacement reaction has occurred (1)\n• The halogen that displaces the most other halogens is the most reactive (1)` },
      { q: 'Explain why the noble gases are unreactive.', marks: 2, markScheme: `• They have a full outer shell of electrons / stable electronic configuration (1)\n• So they do not easily lose, gain or share electrons (1)` },
      { q: 'Explain why helium is used in balloons and airships.', marks: 2, markScheme: `• Helium has a low density / is less dense than air (1)\n• And it is inert / non-flammable, so it is safe (1)` },
      { q: 'Explain why argon is used to fill filament lamps.', marks: 2, markScheme: `• Argon is inert / unreactive (1)\n• So it does not react with the hot filament, which would otherwise burn in oxygen (1)` },
      { q: 'Give one use of neon.', marks: 1, markScheme: `• Advertising signs / neon lights (1)` },
      { q: 'Describe the trends in boiling point and density down Group 0.', marks: 2, markScheme: `• Boiling point increases down the group (1)\n• Density increases down the group (1)` },
      { q: 'The boiling points of helium, neon and argon are −269 °C, −246 °C and −186 °C. Predict the boiling point of krypton, which is below argon.', marks: 1, markScheme: `• Any value between −170 °C and −140 °C (actual −153 °C) (1)` },
      { q: 'Explain why the boiling points of the noble gases increase down the group.', marks: 2, markScheme: `• The atoms get larger down the group (1)\n• So the forces of attraction between atoms get stronger and more energy is needed to overcome them (1)` },
      { q: 'Explain the opposite trends in reactivity down Group 1 and down Group 7.', marks: 4, markScheme: `• Down both groups the outer shell is further from the nucleus / more shielded (1)\n• So attraction between the nucleus and the outer shell electrons is weaker (1)\n• Group 1: outer electron is lost more easily, so reactivity increases (1)\n• Group 7: an electron is gained less easily, so reactivity decreases (1)` },
      { q: 'Fluorine is at the top of Group 7. Predict and explain how fluorine would react with potassium bromide solution.', marks: 2, markScheme: `• Fluorine would displace bromine / an orange colour would form (1)\n• Because fluorine is more reactive than bromine (1)` },
      { q: 'Draw a dot-and-cross diagram for a molecule of chlorine, Cl₂. Show the outer shell electrons only.', marks: 2, diagram: true, markScheme: `Diagram should show:\n• One shared pair of electrons between the two chlorine atoms (1)\n• Six non-bonding electrons on each chlorine atom (8 in total around each) (1)` },
      { q: 'State the name of the compound formed when potassium reacts with iodine, and give its formula.', marks: 2, markScheme: `• Potassium iodide (1)\n• KI (1)` },
      { q: 'Caesium is near the bottom of Group 1. Predict two properties of caesium.', marks: 2, markScheme: `• Very reactive / reacts explosively with water (1)\n• Low melting point / soft / forms a 1+ ion / forms an alkaline hydroxide (1)` },
      { q: '[6 marks] Describe and explain the trend in reactivity of the Group 1 metals, using their reactions with water as evidence.', marks: 6, markScheme: `Indicative content:\n• Lithium, sodium and potassium all react with water to form a metal hydroxide and hydrogen (1)\n• Lithium fizzes steadily; sodium fizzes rapidly and melts; potassium reacts violently and the hydrogen ignites with a lilac flame (1)\n• So reactivity increases down the group (1)\n• Each atom has one outer electron that is lost in the reaction to form a 1+ ion (1)\n• Down the group the outer electron is further from the nucleus with more shielding (1)\n• So the attraction is weaker and the outer electron is lost more easily (1)\nLevel 3 (5–6 marks): observations used as evidence, with a full explanation in terms of electronic structure\nLevel 2 (3–4 marks): the trend is described with some observations or a partial explanation\nLevel 1 (1–2 marks): simple statements of the trend or of observations, with little explanation` },
      { q: '[6 marks] A student has solutions of chlorine, bromine and iodine and solutions of potassium chloride, potassium bromide and potassium iodide. Explain how these solutions could be used to show the trend in reactivity of the halogens, including the expected observations and an explanation of the trend.', marks: 6, markScheme: `Indicative content:\n• Add each halogen solution to each of the other potassium halide solutions (1)\n• Chlorine displaces bromine (orange) from potassium bromide and iodine (brown) from potassium iodide (1)\n• Bromine displaces iodine from potassium iodide but does not react with potassium chloride (1)\n• Iodine does not displace chlorine or bromine, so reactivity decreases down the group: Cl > Br > I (1)\n• Down the group the outer shell is further from the nucleus with more shielding (1)\n• So it is harder to attract the extra electron needed to form a 1− ion (1)\nLevel 3 (5–6 marks): a clear method with correct observations, the trend deduced and fully explained\nLevel 2 (3–4 marks): a method with some correct observations and the trend stated\nLevel 1 (1–2 marks): isolated relevant statements about displacement or reactivity` },
    ]
  },

  /* ─────────────────────────── Topic 7 */
  '7': {
    name: 'Rates of Reaction and Energy Changes',
    questions: [
      { q: 'State four factors that affect the rate of a chemical reaction.', marks: 4, markScheme: `• Temperature (1)\n• Concentration of solutions / pressure of gases (1)\n• Surface area of solids (1)\n• Use of a catalyst (1)` },
      { q: 'State what is meant by the activation energy of a reaction.', marks: 1, markScheme: `• The minimum amount of energy that particles must have to react when they collide (1)` },
      { q: 'Explain, using collision theory, why increasing the concentration of an acid increases the rate of its reaction with marble chips.', marks: 3, markScheme: `• There are more acid particles in the same volume (1)\n• So collisions between particles happen more frequently (1)\n• So there are more successful collisions per second (1)` },
      { q: 'Explain, using collision theory, why increasing the temperature increases the rate of reaction.', marks: 4, markScheme: `• Particles have more kinetic energy and move faster (1)\n• So they collide more frequently (1)\n• A greater proportion of collisions have energy equal to or greater than the activation energy (1)\n• So there are more successful collisions per second (1)` },
      { q: 'Explain why powdered calcium carbonate reacts faster with hydrochloric acid than the same mass of large marble chips.', marks: 3, markScheme: `• The powder has a larger surface area to volume ratio (1)\n• More particles are exposed to the acid (1)\n• So collisions are more frequent (1)` },
      { q: 'Explain why increasing the pressure of a reacting gas increases the rate of reaction.', marks: 2, markScheme: `• The gas particles are closer together / more particles in the same volume (1)\n• So collisions are more frequent (1)` },
      { q: 'Explain how a catalyst increases the rate of a reaction.', marks: 2, markScheme: `• It provides an alternative reaction pathway (1)\n• With a lower activation energy (1)` },
      { q: 'State two features of a catalyst, other than that it speeds up a reaction.', marks: 2, markScheme: `• It is not used up / is chemically unchanged at the end of the reaction (1)\n• Only small amounts are needed / it does not change the products (1)` },
      { q: 'State what is meant by an enzyme.', marks: 1, markScheme: `• A biological catalyst (a protein) (1)` },
      { q: 'Give one industrial use of enzymes.', marks: 1, markScheme: `• Fermentation to make alcoholic drinks / production of bread / biological washing powders (1)` },
      { q: 'Draw a reaction profile for an exothermic reaction with and without a catalyst. Label the activation energy and the overall energy change.', marks: 4, diagram: true, markScheme: `Diagram should show:\n• Products at a lower energy level than reactants (1)\n• Curve rising to a peak then falling, with activation energy labelled from reactants to the peak (1)\n• Overall energy change labelled from reactants to products (1)\n• A second curve with a lower peak for the catalysed reaction (1)` },
      { q: 'Describe how to measure the rate of reaction between marble chips and hydrochloric acid by collecting the gas produced.', marks: 4, markScheme: `• Add a measured mass of marble chips to a measured volume of hydrochloric acid in a conical flask (1)\n• Connect a delivery tube to a gas syringe / upturned measuring cylinder filled with water (1)\n• Start a stopwatch as soon as the acid and chips are mixed and the bung is inserted (1)\n• Record the volume of gas at regular intervals, e.g. every 30 s (1)` },
      { q: 'Describe how the rate of the reaction between marble chips and hydrochloric acid could be followed by measuring a change in mass.', marks: 3, markScheme: `• Place the flask on a balance with a cotton wool plug in the neck (1)\n• Record the mass at regular time intervals (1)\n• The mass decreases as carbon dioxide escapes; the rate is the mass lost per unit time (1)` },
      { q: 'In the reaction between sodium thiosulfate and hydrochloric acid, a cross under the flask disappears. Explain why.', marks: 2, markScheme: `• A precipitate of sulfur forms (1)\n• Which makes the solution cloudy / opaque so the cross cannot be seen (1)` },
      { q: 'Core practical: describe how you would use the reaction between sodium thiosulfate and hydrochloric acid to investigate the effect of temperature on rate.', marks: 4, markScheme: `• Warm a fixed volume of sodium thiosulfate solution to a measured temperature in a water bath (1)\n• Place the flask on a cross drawn on paper and add a fixed volume of hydrochloric acid, starting a timer (1)\n• Record the time for the cross to disappear when viewed from above (1)\n• Repeat at different temperatures, keeping volumes and concentrations the same; rate ∝ 1/time (1)` },
      { q: 'Give two control variables when investigating the effect of acid concentration on the rate of reaction between marble chips and hydrochloric acid.', marks: 2, markScheme: `• Mass and size (surface area) of marble chips (1)\n• Volume of acid / temperature (1)` },
      { q: 'A reaction produced 60 cm³ of gas in 30 s. Calculate the mean rate of reaction in cm³/s.', marks: 2, markScheme: `• Mean rate = volume ÷ time = 60 ÷ 30 (1)\n• = 2.0 cm³/s (1)` },
      { q: 'In a reaction 0.40 g of magnesium was used up in 2.0 minutes. Calculate the mean rate of reaction in g/s.', marks: 3, markScheme: `• Time = 2.0 × 60 = 120 s (1)\n• Mean rate = 0.40 ÷ 120 (1)\n• = 0.0033 g/s (3.3 × 10⁻³ g/s) (1)` },
      { q: 'Describe how to use a graph of volume of gas against time to find the rate of reaction at a particular time. [HT]', marks: 3, markScheme: `• Draw a tangent to the curve at that time (1)\n• Calculate the gradient of the tangent: change in volume ÷ change in time, using a large triangle (1)\n• The gradient is the rate at that time, in cm³/s (1)` },
      { q: 'Sketch a graph of volume of gas against time for the reaction of marble chips with excess hydrochloric acid. On the same axes, sketch the curve you would expect for the same mass of powdered calcium carbonate.', marks: 3, diagram: true, markScheme: `Sketch should show:\n• Curve starting at the origin, steep at first and then levelling off (1)\n• Powder curve steeper at the start (1)\n• Both curves levelling off at the same final volume (1)` },
      { q: 'Explain why the graph of volume of gas against time for the reaction of marble chips with hydrochloric acid becomes horizontal.', marks: 2, markScheme: `• One of the reactants has been used up (1)\n• So the reaction has stopped and no more gas is produced (1)` },
      { q: 'Explain why the rate of reaction is fastest at the start of a reaction.', marks: 2, markScheme: `• The concentration of reactants is highest at the start (1)\n• So the frequency of collisions is greatest (1)` },
      { q: 'State what is meant by an exothermic reaction and give one example.', marks: 2, markScheme: `• A reaction that transfers heat energy to the surroundings, so the temperature of the surroundings increases (1)\n• Example: combustion / neutralisation / respiration / displacement (1)` },
      { q: 'State what is meant by an endothermic reaction and give one example.', marks: 2, markScheme: `• A reaction that takes in heat energy from the surroundings, so the temperature of the surroundings decreases (1)\n• Example: thermal decomposition / photosynthesis / dissolving ammonium nitrate / reaction of citric acid with sodium hydrogencarbonate (1)` },
      { q: 'Explain, in terms of bonds, why a reaction is exothermic.', marks: 3, markScheme: `• Breaking bonds is endothermic / takes in energy (1)\n• Making bonds is exothermic / releases energy (1)\n• In an exothermic reaction more energy is released making new bonds than is taken in breaking bonds (1)` },
      { q: 'Describe how to investigate the temperature change when dilute hydrochloric acid is neutralised by sodium hydroxide solution.', marks: 4, markScheme: `• Measure a known volume of acid into a polystyrene cup and record its starting temperature (1)\n• Add a measured volume of sodium hydroxide solution (1)\n• Stir and record the highest temperature reached (1)\n• Calculate the temperature change; repeat for reliability (1)` },
      { q: 'Explain why a polystyrene cup with a lid is used when measuring temperature changes in reactions.', marks: 2, markScheme: `• Polystyrene is a good thermal insulator / the lid reduces heat loss (1)\n• So less energy is transferred to the surroundings and the temperature change is more accurate (1)` },
      { q: 'A student mixes solutions and the temperature falls from 21.5 °C to 16.0 °C. Calculate the temperature change and state whether the reaction is exothermic or endothermic.', marks: 2, markScheme: `• Temperature change = −5.5 °C / decrease of 5.5 °C (1)\n• Endothermic (1)` },
      { q: 'Use the bond energies to calculate the energy change for the reaction H₂ + Cl₂ → 2HCl. (H–H = 436 kJ mol⁻¹, Cl–Cl = 242 kJ mol⁻¹, H–Cl = 431 kJ mol⁻¹) [HT]', marks: 3, markScheme: `• Energy to break bonds = 436 + 242 = 678 kJ mol⁻¹ (1)\n• Energy released making bonds = 2 × 431 = 862 kJ mol⁻¹ (1)\n• Energy change = 678 − 862 = −184 kJ mol⁻¹ (1)` },
      { q: 'Use the bond energies to calculate the energy change for the combustion of methane: CH₄ + 2O₂ → CO₂ + 2H₂O. (C–H = 413, O=O = 498, C=O = 805, O–H = 464, all in kJ mol⁻¹) State whether the reaction is exothermic or endothermic. [HT]', marks: 4, markScheme: `• Bonds broken = (4 × 413) + (2 × 498) = 1652 + 996 = 2648 kJ mol⁻¹ (1)\n• Bonds made = (2 × 805) + (4 × 464) = 1610 + 1856 = 3466 kJ mol⁻¹ (1)\n• Energy change = 2648 − 3466 = −818 kJ mol⁻¹ (1)\n• Exothermic, because the energy change is negative (1)` },
      { q: 'Use the bond energies to calculate the energy change for the reaction N₂ + 3H₂ → 2NH₃. (N≡N = 945, H–H = 436, N–H = 391, all in kJ mol⁻¹) [HT]', marks: 3, markScheme: `• Bonds broken = 945 + (3 × 436) = 2253 kJ mol⁻¹ (1)\n• Bonds made = 6 × 391 = 2346 kJ mol⁻¹ (1)\n• Energy change = 2253 − 2346 = −93 kJ mol⁻¹ (1)` },
      { q: 'Draw a reaction profile for an endothermic reaction. Label the reactants, products, activation energy and overall energy change.', marks: 3, diagram: true, markScheme: `Diagram should show:\n• Products at a higher energy level than reactants (1)\n• Activation energy labelled from the reactants to the peak of the curve (1)\n• Overall energy change labelled as the difference between reactants and products (1)` },
      { q: 'Explain why a reaction with a high activation energy is very slow at room temperature.', marks: 2, markScheme: `• Only a very small proportion of particles have energy equal to or greater than the activation energy (1)\n• So very few collisions are successful (1)` },
      { q: 'A student investigates the effect of a catalyst on the decomposition of hydrogen peroxide. Describe how the student could show that manganese(IV) oxide acts as a catalyst and is not used up.', marks: 4, markScheme: `• Measure the volume of oxygen produced over time with and without the manganese(IV) oxide (1)\n• Faster production of oxygen with manganese(IV) oxide shows it increases the rate (1)\n• Weigh the manganese(IV) oxide before the reaction and filter, dry and reweigh it afterwards (1)\n• The mass is unchanged, showing it has not been used up (1)` },
      { q: 'Explain why reaction rates are important in industry.', marks: 2, markScheme: `• Faster reactions produce more product in a given time, increasing profit (1)\n• But conditions to increase rate (e.g. high temperature or pressure) cost money, so a balance must be found (1)` },
      { q: 'Explain why a hand warmer containing iron powder gets hot when the iron reacts with oxygen.', marks: 2, markScheme: `• The reaction is exothermic (1)\n• Energy is transferred to the surroundings (the hand) / more energy is released making bonds than breaking them (1)` },
      { q: 'A reaction was carried out at 20 °C and took 80 s to finish. Predict the time taken at 30 °C, given that a 10 °C rise roughly doubles the rate, and explain your answer.', marks: 2, markScheme: `• About 40 s (1)\n• Because the rate doubles, so the time taken halves (1)` },
      { q: 'Explain why a cold pack containing ammonium nitrate and water feels cold.', marks: 2, markScheme: `• Dissolving ammonium nitrate is endothermic (1)\n• Energy is taken in from the surroundings, so the temperature decreases (1)` },
      { q: '[6 marks] Core practical: describe how to investigate the effect of acid concentration on the rate of reaction between marble chips and hydrochloric acid by measuring the volume of gas produced. Include how the results would be processed.', marks: 6, markScheme: `Indicative content:\n• Measure a fixed volume of hydrochloric acid of known concentration into a conical flask (1)\n• Add a fixed mass of marble chips of the same size, quickly insert the bung and start the timer (1)\n• Collect the gas in a gas syringe / upturned measuring cylinder and record the volume every 30 s (1)\n• Repeat with different concentrations of acid, keeping the temperature, mass and size of chips and volume of acid the same (1)\n• Plot graphs of volume of gas against time for each concentration (1)\n• Compare the initial gradients / calculate the mean rate = volume ÷ time to show how rate changes with concentration (1)\nLevel 3 (5–6 marks): a detailed, logical method with control variables and a clear explanation of how the rate is found\nLevel 2 (3–4 marks): a workable method with some control variables or some processing of results\nLevel 1 (1–2 marks): a few relevant steps with little detail or processing` },
      { q: '[6 marks] Explain how temperature, surface area and a catalyst each affect the rate of reaction, using collision theory and ideas about activation energy.', marks: 6, markScheme: `Indicative content:\n• Increasing temperature gives particles more kinetic energy, so they collide more frequently (1)\n• And a greater proportion of collisions have energy at least equal to the activation energy (1)\n• Increasing surface area (e.g. using powder) exposes more particles of the solid to the other reactant (1)\n• So collisions are more frequent (1)\n• A catalyst provides an alternative pathway with a lower activation energy (1)\n• So a greater proportion of collisions are successful, while the catalyst is not used up (1)\nLevel 3 (5–6 marks): all three factors explained clearly in terms of collision frequency and energy of collisions\nLevel 2 (3–4 marks): at least two factors explained with some use of collision theory\nLevel 1 (1–2 marks): simple statements of the effect of the factors with little explanation` },
    ]
  },

  /* ─────────────────────────── Topic 8 */
  '8': {
    name: 'Fuels and Earth Science',
    questions: [
      { q: 'State what is meant by a hydrocarbon.', marks: 1, markScheme: `• A compound containing hydrogen and carbon only (1)` },
      { q: 'Explain why crude oil is described as a finite resource.', marks: 2, markScheme: `• It was formed over millions of years from the remains of ancient sea organisms (1)\n• It is being used up much faster than it is being formed, so it will run out (1)` },
      { q: 'State why crude oil is described as a complex mixture.', marks: 1, markScheme: `• It contains many different hydrocarbons, mostly alkanes, that are not chemically combined (1)` },
      { q: 'Give two important uses of crude oil.', marks: 2, markScheme: `• As a source of fuels (1)\n• As a feedstock for the petrochemical industry / to make polymers and other chemicals (1)` },
      { q: 'Name four fractions obtained from crude oil and give one use of each.', marks: 4, markScheme: `• Gases — domestic heating and cooking (1)\n• Petrol — fuel for cars (1)\n• Kerosene — fuel for aircraft (1)\n• Diesel oil — fuel for some cars and trains / fuel oil — fuel for ships and power stations / bitumen — road surfaces (1)` },
      { q: 'Describe how crude oil is separated by fractional distillation.', marks: 4, markScheme: `• Crude oil is heated until most of it evaporates (1)\n• The vapours enter a fractionating column that is hot at the bottom and cooler at the top (1)\n• Hydrocarbons condense at different heights depending on their boiling points (1)\n• Fractions with small molecules / low boiling points leave at the top; large molecules / high boiling points leave at the bottom (1)` },
      { q: 'Describe how the properties of hydrocarbons change as the number of carbon atoms in the molecules increases.', marks: 3, markScheme: `• Boiling point increases (1)\n• Viscosity increases / they become less runny (1)\n• Ease of ignition decreases / they become harder to ignite (1)` },
      { q: 'Explain why hydrocarbons with larger molecules have higher boiling points.', marks: 2, markScheme: `• Larger molecules have stronger intermolecular forces (1)\n• So more energy is needed to overcome them (1)` },
      { q: 'State what is meant by a homologous series.', marks: 3, markScheme: `• A family of compounds with the same general formula (1)\n• Neighbouring members differ by CH₂ (1)\n• They have similar chemical properties and a gradual trend in physical properties (1)` },
      { q: 'Give the general formula of the alkanes and use it to write the formula of the alkane with 8 carbon atoms.', marks: 2, markScheme: `• CₙH₂ₙ₊₂ (1)\n• C₈H₁₈ (1)` },
      { q: 'Write the balanced equation for the complete combustion of propane, C₃H₈.', marks: 2, markScheme: `• C₃H₈ + O₂ → CO₂ + H₂O with correct formulae (1)\n• Balanced: C₃H₈ + 5O₂ → 3CO₂ + 4H₂O (1)` },
      { q: 'Pentane, C₅H₁₂, is an alkane. (a) Write the balanced equation for its complete combustion. (b) Write the balanced equation for its incomplete combustion to form carbon monoxide and water. (c) Explain why incomplete combustion transfers less energy than complete combustion.', marks: 5, markScheme: `• (a) C₅H₁₂ + O₂ → CO₂ + H₂O with correct formulae (1)\n• (a) Balanced: C₅H₁₂ + 8O₂ → 5CO₂ + 6H₂O (1)\n• (b) C₅H₁₂ + O₂ → CO + H₂O with correct formulae (1)\n• (b) Balanced: 2C₅H₁₂ + 11O₂ → 10CO + 12H₂O (1)\n• (c) The carbon is not fully oxidised, so less energy is released (1)` },
      { q: 'Explain why incomplete combustion of hydrocarbons occurs and name two products other than water.', marks: 3, markScheme: `• Incomplete combustion occurs when there is a limited supply of oxygen / air (1)\n• Carbon monoxide (1)\n• Carbon (soot) (1)` },
      { q: 'Explain why carbon monoxide is toxic.', marks: 2, markScheme: `• It combines with haemoglobin in red blood cells (1)\n• Reducing the ability of the blood to carry oxygen (1)` },
      { q: 'Give two problems caused by soot from incomplete combustion.', marks: 2, markScheme: `• Causes breathing problems / respiratory illness (1)\n• Blackens buildings / causes global dimming (1)` },
      { q: 'Explain how burning some fuels leads to acid rain.', marks: 3, markScheme: `• Some fuels contain sulfur as an impurity (1)\n• The sulfur burns to form sulfur dioxide (1)\n• Sulfur dioxide dissolves in rainwater to form an acidic solution (1)` },
      { q: 'Explain how oxides of nitrogen are formed in car engines.', marks: 2, markScheme: `• The high temperature inside the engine (1)\n• Makes nitrogen and oxygen from the air react together (1)` },
      { q: 'Give two problems caused by acid rain.', marks: 2, markScheme: `• Damages / corrodes limestone buildings and metal structures (1)\n• Makes lakes acidic, killing fish and other aquatic life / damages trees (1)` },
      { q: 'Evaluate the use of hydrogen as a fuel for cars compared with petrol.', marks: 4, markScheme: `• Advantage: the only product of combustion is water, so no carbon dioxide is released at the point of use (1)\n• Advantage: hydrogen can be made from renewable sources, e.g. electrolysis of water using renewable electricity (1)\n• Disadvantage: hydrogen is a gas that is hard to store and needs large, pressurised tanks; it is highly flammable (1)\n• Disadvantage: few filling stations, and making hydrogen often uses fossil fuels (1)` },
      { q: 'State what is meant by cracking.', marks: 1, markScheme: `• Breaking down long-chain hydrocarbons into shorter, more useful molecules (1)` },
      { q: 'Explain why cracking is needed in the oil industry.', marks: 3, markScheme: `• Crude oil contains more long-chain hydrocarbons than are needed (1)\n• There is a high demand for short-chain hydrocarbons such as petrol (1)\n• Cracking also produces alkenes, used to make polymers (1)` },
      { q: 'Complete the equation for the cracking of decane: C₁₀H₂₂ → C₈H₁₈ + ____', marks: 1, markScheme: `• C₂H₄ (ethene) (1)` },
      { q: 'Describe the conditions used to crack hydrocarbons.', marks: 2, markScheme: `• Heating the hydrocarbon vapour to a high temperature (1)\n• Passing it over a hot catalyst (e.g. silica or alumina) (1)` },
      { q: 'Describe how the Earth\'s early atmosphere was formed.', marks: 2, markScheme: `• Gases were released by volcanic activity (1)\n• The early atmosphere was mainly carbon dioxide and water vapour, with little or no oxygen (1)` },
      { q: 'Explain how the oceans were formed.', marks: 2, markScheme: `• The Earth cooled (1)\n• So water vapour condensed to form the oceans (1)` },
      { q: 'Explain how the amount of oxygen in the atmosphere increased.', marks: 2, markScheme: `• Primitive plants / algae evolved and carried out photosynthesis (1)\n• Photosynthesis takes in carbon dioxide and releases oxygen (1)` },
      { q: 'Describe the test for oxygen gas.', marks: 2, markScheme: `• Insert a glowing splint into the gas (1)\n• The splint relights (1)` },
      { q: 'Explain how the proportion of carbon dioxide in the atmosphere decreased over time.', marks: 3, markScheme: `• Carbon dioxide dissolved in the oceans (1)\n• It was used by plants / algae in photosynthesis (1)\n• Carbon was locked up in sedimentary rocks (e.g. limestone) and fossil fuels (1)` },
      { q: 'Give the approximate percentages of nitrogen and oxygen in today\'s dry atmosphere.', marks: 2, markScheme: `• Nitrogen: about 78% (1)\n• Oxygen: about 21% (1)` },
      { q: 'Explain why evidence about the Earth\'s early atmosphere is limited.', marks: 2, markScheme: `• The early atmosphere formed billions of years ago (1)\n• So there are no direct measurements and little preserved evidence (1)` },
      { q: 'Explain how greenhouse gases keep the Earth warmer than it would otherwise be.', marks: 4, markScheme: `• The Sun emits short-wavelength radiation that passes through the atmosphere and warms the Earth\'s surface (1)\n• The Earth emits longer-wavelength infrared radiation (1)\n• Greenhouse gases absorb some of this infrared radiation (1)\n• And re-emit it in all directions, including back towards the Earth, warming the lower atmosphere (1)` },
      { q: 'Name three greenhouse gases.', marks: 3, markScheme: `• Carbon dioxide (1)\n• Methane (1)\n• Water vapour (1)` },
      { q: 'Describe two human activities that increase the amount of methane in the atmosphere.', marks: 2, markScheme: `• Farming cattle / livestock (1)\n• Rice paddy fields / decomposition of waste in landfill sites (1)` },
      { q: 'Describe two human activities that increase the amount of carbon dioxide in the atmosphere.', marks: 2, markScheme: `• Burning fossil fuels (1)\n• Deforestation (1)` },
      { q: 'Explain why there is a correlation between atmospheric carbon dioxide levels and global temperature, but scientists are cautious about saying one causes the other.', marks: 3, markScheme: `• Both carbon dioxide levels and mean global temperature have increased since the industrial revolution (1)\n• Increased carbon dioxide absorbs more infrared radiation, providing a mechanism for warming (1)\n• But other factors (e.g. solar activity) also affect temperature, so correlation alone does not prove cause (1)` },
      { q: 'Give three possible effects of climate change.', marks: 3, markScheme: `• Rising sea levels / flooding of coastal areas (1)\n• More frequent extreme weather events (1)\n• Changes in food production / distribution of species / melting polar ice caps (1)` },
      { q: 'Suggest two ways of reducing carbon dioxide emissions.', marks: 2, markScheme: `• Using renewable energy sources instead of fossil fuels (1)\n• Improving energy efficiency / carbon capture and storage / planting trees (1)` },
      { q: 'Explain why historical data for carbon dioxide levels and temperature are less accurate than modern data.', marks: 2, markScheme: `• Historical data comes from indirect sources such as ice cores / tree rings (1)\n• Fewer measurements were taken in fewer locations, so data is less precise / representative (1)` },
      { q: '[6 marks] Describe how the composition of the Earth\'s atmosphere has changed from the early atmosphere to today, and explain the processes responsible.', marks: 6, markScheme: `Indicative content:\n• The early atmosphere formed from volcanic gases and was mainly carbon dioxide and water vapour, with little or no oxygen (1)\n• As the Earth cooled, water vapour condensed to form the oceans (1)\n• Carbon dioxide dissolved in the oceans and was locked up in sedimentary rocks such as limestone (1)\n• Plants and algae evolved and photosynthesis removed carbon dioxide and released oxygen (1)\n• Carbon was also locked up in fossil fuels formed from dead organisms (1)\n• Today the atmosphere is about 78% nitrogen, 21% oxygen and small amounts of argon and carbon dioxide (about 0.04%) (1)\nLevel 3 (5–6 marks): a detailed, sequenced account of the changes with clear explanations of the processes\nLevel 2 (3–4 marks): describes some changes with some processes explained\nLevel 1 (1–2 marks): simple statements about the early or present atmosphere with little explanation` },
      { q: '[6 marks] Explain how human activities are thought to cause climate change, and evaluate the evidence for this.', marks: 6, markScheme: `Indicative content:\n• Burning fossil fuels releases carbon dioxide; deforestation reduces carbon dioxide removal by photosynthesis (1)\n• Farming cattle and landfill increase methane levels (1)\n• These greenhouse gases absorb and re-emit infrared radiation, increasing the greenhouse effect and global temperature (1)\n• Evidence: measured carbon dioxide levels and mean global temperatures have both risen since the industrial revolution (1)\n• Correlation does not prove causation; other factors such as solar activity could contribute, and historical data from ice cores is less precise (1)\n• Most scientists agree, based on peer-reviewed evidence and climate models, that human activity is very likely to be the main cause (1)\nLevel 3 (5–6 marks): clear explanation of the mechanism with a balanced evaluation of the evidence and its limitations\nLevel 2 (3–4 marks): explains how some human activities increase greenhouse gases, with some reference to evidence\nLevel 1 (1–2 marks): simple statements about human activities or greenhouse gases` },
    ]
  },

  /* ─────────────────────────── Topic 9 */
  '9': {
    name: 'Separate Chemistry 2',
    questions: [
      { q: 'Describe how to carry out a flame test on a solid sample.', marks: 3, markScheme: `• Clean a nichrome / platinum wire loop by dipping it in concentrated hydrochloric acid and heating it in a Bunsen flame (1)\n• Dip the loop in the solid sample (moistened with acid) (1)\n• Hold the loop in the hottest / blue part of a Bunsen flame and observe the colour (1)` },
      { q: 'Give the flame test colour for each ion: (a) lithium, Li⁺, (b) sodium, Na⁺, (c) potassium, K⁺, (d) calcium, Ca²⁺, (e) copper, Cu²⁺.', marks: 5, markScheme: `• (a) Red / crimson (1)\n• (b) Yellow (1)\n• (c) Lilac (1)\n• (d) Orange-red (1)\n• (e) Blue-green (1)` },
      { q: 'Explain why flame tests cannot always identify the metal ions in a mixture.', marks: 2, markScheme: `• Some flame colours mask others, e.g. the yellow of sodium hides other colours (1)\n• So a mixture may show only one colour / colours are hard to distinguish (1)` },
      { q: 'Describe how a flame photometer can be used to identify a metal ion and find its concentration in a solution.', marks: 4, markScheme: `• The solution is sprayed into a flame and the light emitted is analysed to give a spectrum (1)\n• Each metal ion gives a characteristic spectrum, which is compared with reference spectra to identify it (1)\n• The intensity of the emitted light is measured for standard solutions of known concentration to make a calibration curve (1)\n• The concentration of the sample is read from the calibration curve using its measured intensity (1)` },
      { q: 'Give two advantages of using instrumental methods, such as flame photometry, compared with chemical tests.', marks: 2, markScheme: `• More sensitive / can detect very small amounts (1)\n• More accurate / faster / can analyse mixtures (1)` },
      { q: 'Sodium hydroxide solution is added to solutions of metal ions. Give the colour of the precipitate formed with (a) Cu²⁺, (b) Fe²⁺ and (c) Fe³⁺.', marks: 3, markScheme: `• (a) Blue (1)\n• (b) Green (1)\n• (c) Orange-brown (1)` },
      { q: 'Aluminium ions and calcium ions both give a white precipitate with sodium hydroxide solution. Describe how to distinguish between them.', marks: 2, markScheme: `• Add excess sodium hydroxide solution (1)\n• The aluminium hydroxide precipitate dissolves to give a colourless solution; calcium hydroxide does not dissolve (1)` },
      { q: 'Write the ionic equation for the reaction of iron(II) ions with hydroxide ions. Include state symbols. [HT]', marks: 2, markScheme: `• Fe²⁺ + 2OH⁻ → Fe(OH)₂ (1)\n• State symbols: (aq) + (aq) → (s) (1)` },
      { q: 'Describe the test for ammonium ions.', marks: 3, markScheme: `• Add sodium hydroxide solution and warm gently (1)\n• Ammonia gas is given off (1)\n• Which turns damp red litmus paper blue (1)` },
      { q: 'Describe the test for carbonate ions.', marks: 3, markScheme: `• Add dilute acid (1)\n• Bubbles of gas are produced (1)\n• The gas turns limewater milky, showing it is carbon dioxide (1)` },
      { q: 'Describe the test for sulfate ions.', marks: 3, markScheme: `• Add dilute hydrochloric acid (1)\n• Then add barium chloride solution (1)\n• A white precipitate forms (1)` },
      { q: 'Explain why dilute hydrochloric acid is added before barium chloride solution in the test for sulfate ions.', marks: 2, markScheme: `• To remove carbonate ions (1)\n• Which would also form a white precipitate with barium ions, giving a false positive (1)` },
      { q: 'Describe the test for halide ions and give the result for chloride, bromide and iodide ions.', marks: 4, markScheme: `• Add dilute nitric acid, then silver nitrate solution (1)\n• Chloride: white precipitate (1)\n• Bromide: cream precipitate (1)\n• Iodide: yellow precipitate (1)` },
      { q: 'A solid gives a lilac flame and forms a yellow precipitate with acidified silver nitrate solution. Identify the solid.', marks: 2, markScheme: `• Contains potassium ions (1)\n• And iodide ions, so it is potassium iodide (1)` },
      { q: '[6 marks] Core practical: you are given three unlabelled white solids: sodium chloride, ammonium sulfate and potassium carbonate. Describe tests to identify each solid, giving the expected results.', marks: 6, markScheme: `Indicative content:\n• Flame test: sodium chloride gives a yellow flame, potassium carbonate gives a lilac flame (1)\n• Add sodium hydroxide solution and warm: only ammonium sulfate gives off ammonia (1)\n• Ammonia turns damp red litmus paper blue (1)\n• Add dilute acid: only potassium carbonate fizzes, and the gas turns limewater milky (1)\n• Add dilute hydrochloric acid then barium chloride solution: ammonium sulfate gives a white precipitate (1)\n• Add dilute nitric acid then silver nitrate solution: sodium chloride gives a white precipitate (1)\nLevel 3 (5–6 marks): a logical sequence of tests that identifies all three solids with correct results\nLevel 2 (3–4 marks): correct tests and results for at least two ions, identifying at least one solid\nLevel 1 (1–2 marks): one or two relevant tests named with limited or incorrect results` },
      { q: 'State what is meant by a saturated hydrocarbon.', marks: 1, markScheme: `• A hydrocarbon that contains only single bonds between carbon atoms (1)` },
      { q: 'Give the general formula of the alkenes and name the alkene with three carbon atoms.', marks: 2, markScheme: `• CₙH₂ₙ (1)\n• Propene (1)` },
      { q: 'Describe a test to distinguish between an alkane and an alkene.', marks: 3, markScheme: `• Add bromine water to each (1)\n• The alkene turns bromine water from orange to colourless (1)\n• The alkane does not change the colour / it stays orange (1)` },
      { q: 'Write the equation for the reaction of ethene with bromine and name the product.', marks: 2, markScheme: `• C₂H₄ + Br₂ → C₂H₄Br₂ (1)\n• 1,2-dibromoethane (1)` },
      { q: 'Write the balanced equation for the complete combustion of ethene.', marks: 2, markScheme: `• C₂H₄ + O₂ → CO₂ + H₂O with correct formulae (1)\n• Balanced: C₂H₄ + 3O₂ → 2CO₂ + 2H₂O (1)` },
      { q: 'Name the functional group present in alcohols and give the formula of propanol.', marks: 2, markScheme: `• Hydroxyl group, –OH (1)\n• C₃H₇OH (1)` },
      { q: 'Name the carboxylic acid with two carbon atoms and give its functional group.', marks: 2, markScheme: `• Ethanoic acid (1)\n• –COOH (1)` },
      { q: 'Describe how ethanol is produced by fermentation.', marks: 4, markScheme: `• A solution of sugar (glucose) is mixed with yeast (1)\n• At a temperature of about 30–35 °C (1)\n• Under anaerobic conditions / with air kept out (1)\n• Yeast enzymes convert the sugar into ethanol and carbon dioxide (1)` },
      { q: 'Explain why the temperature must be controlled during fermentation.', marks: 2, markScheme: `• Too low a temperature makes the reaction too slow (1)\n• Too high a temperature denatures the enzymes in the yeast (1)` },
      { q: 'Explain how a concentrated solution of ethanol is obtained from the dilute solution produced by fermentation.', marks: 2, markScheme: `• Filter to remove the yeast, then use fractional distillation (1)\n• Ethanol has a lower boiling point than water, so it distils off first (1)` },
      { q: 'Ethanol can be oxidised. Name the type of compound formed and name the product.', marks: 2, markScheme: `• Carboxylic acid (1)\n• Ethanoic acid (1)` },
      { q: 'Describe what you would observe when ethanoic acid is added to sodium carbonate, and name the products.', marks: 3, markScheme: `• Fizzing / effervescence (1)\n• Products: sodium ethanoate and water (1)\n• And carbon dioxide (1)` },
      { q: '[6 marks] Core practical: describe how to investigate the temperature rise produced in a known mass of water by the combustion of different alcohols, and how to make the comparison fair.', marks: 6, markScheme: `Indicative content:\n• Weigh a spirit burner containing the alcohol, with its cap on (1)\n• Measure a fixed volume / mass of water into a copper calorimeter / can and record its starting temperature (1)\n• Light the burner under the calorimeter and stir the water (1)\n• Stop when the temperature has risen by a fixed amount (e.g. 20 °C), extinguish the flame, and reweigh the burner (1)\n• Calculate the mass of alcohol burned and the temperature rise per gram of alcohol (1)\n• Fair test: same distance between flame and calorimeter, same volume of water, use draught shields / a lid; repeat for each alcohol (1)\nLevel 3 (5–6 marks): a detailed, logical method with measurements, processing of results and control variables\nLevel 2 (3–4 marks): a workable method with some measurements and some control variables\nLevel 1 (1–2 marks): a few relevant steps with little detail` },
      { q: 'State what is meant by an addition polymer.', marks: 2, markScheme: `• A long-chain molecule formed when many small monomer molecules join together (1)\n• Monomers contain a C=C double bond, and no other product is formed (1)` },
      { q: 'Draw the repeating unit of poly(propene), formed from propene, CH₂=CHCH₃.', marks: 2, diagram: true, markScheme: `Diagram should show:\n• Two carbon atoms joined by a single bond, with H, H on one carbon and H, CH₃ on the other (1)\n• Brackets with extension bonds through them and n outside (1)` },
      { q: 'Give one use of each polymer and link it to a property: (a) poly(ethene), (b) poly(chloroethene) (PVC), (c) PTFE.', marks: 3, markScheme: `• (a) Plastic bags / bottles — flexible, cheap, strong (1)\n• (b) Window frames / water pipes / electrical insulation — strong, durable, rigid (1)\n• (c) Non-stick coatings for pans — slippery, unreactive, high melting point (1)` },
      { q: 'Explain how a condensation polymer, such as a polyester, is formed. [HT]', marks: 3, markScheme: `• Two different monomers, each with two functional groups, react — a diol and a dicarboxylic acid (1)\n• They join together in alternating units forming ester links (1)\n• A small molecule, water, is formed for each link made (1)` },
      { q: 'Name the monomers that make up (a) DNA, (b) proteins and (c) starch.', marks: 3, markScheme: `• (a) Nucleotides (1)\n• (b) Amino acids (1)\n• (c) Glucose (1)` },
      { q: 'Explain the problems caused by the disposal of polymers.', marks: 3, markScheme: `• Most polymers are not biodegradable, so they persist in landfill / the environment for many years (1)\n• Burning polymers releases carbon dioxide and can release toxic gases (1)\n• Landfill sites are running out of space / litter harms wildlife (1)` },
      { q: 'Give two advantages and one disadvantage of recycling polymers.', marks: 3, markScheme: `• Advantage: reduces the amount of crude oil used (1)\n• Advantage: reduces waste in landfill (1)\n• Disadvantage: polymers must be sorted / collection and sorting is expensive and uses energy (1)` },
      { q: 'Compare the properties of ceramics, polymers and metals.', marks: 3, markScheme: `• Ceramics: hard, brittle, high melting points, electrical insulators (1)\n• Polymers: flexible, low density, low melting points, electrical insulators (1)\n• Metals: malleable, good conductors of heat and electricity, high density (1)` },
      { q: 'Explain what is meant by a composite material and give one example.', marks: 2, markScheme: `• A material made from two or more different materials combined, a matrix and a reinforcement, with improved properties (1)\n• Example: fibreglass / carbon-fibre-reinforced polymer / reinforced concrete (1)` },
      { q: 'State the size range of nanoparticles and explain why they have different properties from the same material in bulk.', marks: 3, markScheme: `• 1–100 nm (1)\n• Nanoparticles have a very high surface area to volume ratio (1)\n• So a much larger proportion of their atoms are at the surface and can react (1)` },
      { q: 'A cube-shaped nanoparticle has sides of 10 nm. Calculate its surface area to volume ratio.', marks: 3, markScheme: `• Surface area = 6 × 10 × 10 = 600 nm² (1)\n• Volume = 10 × 10 × 10 = 1000 nm³ (1)\n• Ratio = 600 ÷ 1000 = 0.6 (nm⁻¹) (1)` },
      { q: '[6 marks] Evaluate the use of nanoparticles in products such as sunscreens and catalysts.', marks: 6, markScheme: `Indicative content:\n• Nanoparticles have a very high surface area to volume ratio (1)\n• So smaller amounts are needed as catalysts, saving costs and resources (1)\n• In sunscreens, nanoparticles (e.g. titanium dioxide) block UV light without leaving a white mark on the skin (1)\n• Nanoparticles may be absorbed through the skin or breathed in and enter cells (1)\n• Their long-term effects on health and the environment are not fully known / they may be released into water (1)\n• Justified conclusion, e.g. benefits are significant but more research and testing are needed (1)\nLevel 3 (5–6 marks): a balanced evaluation of benefits and risks with a justified conclusion\nLevel 2 (3–4 marks): some benefits and risks given, linked to properties\nLevel 1 (1–2 marks): simple statements about uses or risks of nanoparticles` },
    ]
  },

};

